/* Boş kitap bölümlerine özgün öğretmen açıklamaları. Kimlik+başlık+basılı kaynak sayfalarıyla eşlenir. */
(function () {
  const patch = (id, title, pages, explanation, look, question, answer) => {
    const guide = (window.BOOK_GUIDES || {})[id];
    const section = guide?.sections.find(s => s.title === title && s.pages.join(',') === pages.join(','));
    if (!section) throw new Error('Kitap bölümü eşleşmedi: ' + id + ' / ' + title);
    if ((section.explanation || []).length || (section.notes || []).some(n => String(n.text || '').trim())) return;
    section.explanation = explanation;
    section.look = look;
    section.check = { question, answer };
  };

  patch('tur-02', 'Sözcükte Anlam 3', [12,13], [
    'Bu sayfalarda anlam aktarımını belirleyen soru, iki kavram arasında benzerlik kurulup kurulmadığıdır. “Tribün karara itiraz etti.” sözünde tribünün yapısı değil oradaki insanlar kastedilir; yer-insan bağıyla ad aktarması vardır. “Bulutlar somurtuyordu.” sözünde ise insana ait tutum doğaya taşınır. Duyular arası aktarmada duyma, görme, dokunma gibi alanları ayır: “kadife ses” ifadesi dokunma özelliğini işitme alanında kullanır. Aktarmayı yalnız alışılmadık sözcüğü bulmakla değil, özelliğin nereden nereye taşındığını göstererek açıklarsın.',
    'Kinayede gerçek okuma mümkün kalırken asıl amaç mecazdır; tarizde amaç söylenenin tersini sezdirmektir. Dolaylama bir kavramı birden fazla sözcükle karşılarken güzel adlandırma ürkütücü bir gerçeğin çağrışımını yumuşatır. Anlam genişlemesi ve daralması ise tek cümledeki sanat değil, sözcüğün zaman içindeki kapsam değişimidir. Bugünkü kullanımdan geçmiş anlamı kendin tahmin etme; karşılaştırma verildiyse eski ve yeni kapsamın sınırlarına bak.'
  ], '12. sayfada ad aktarmasının ilişki türlerini;13. sayfada kinaye-tariz ayrımı ile tarihsel anlam değişimlerini karşılaştır.', '“Sınavdan sıfır aldın; müthiş hazırlanmışsın!” sözünde hangi anlam olayı baskındır?', 'Tariz vardır. Olumlu görünen hazırlık övgüsü, verilen sonuçla ters düşerek eleştiri anlamı taşır.');
  patch('tur-02', 'Sözcükte Anlam 4', [14], [
    'Atasözü genelleştirilmiş deneyim veya öğüt bildirir; deyim ise belirli bir durumu kalıplaşmış bir anlatımla adlandırır. Deyimin cümle biçiminde kurulması onu atasözüne dönüştürmez. “İpe un sermek” bir davranışı anlatır, herkesin nasıl davranması gerektiğini söyleyen genel bir hüküm kurmaz. İki türde de sözcükleri eş anlamlılarıyla değiştirmek kalıbı bozabilir. Bu yüzden yalnız sözcük sayısı veya fiilin çekimli olması üzerinden sınıflandırma yapılmaz.',
    'İkileme anlatımı pekiştiren iki öğenin birlikte kullanılmasıdır; aynı sözcük, yakın/zıt anlamlı sözler veya anlamlı-anlamsız öğelerle oluşabilir. “Az çok” zıt anlam ilişkisiyle, “yavaş yavaş” aynı sözcüğün tekrarıyla kurulur. İkilemenin kuruluş türü ile cümledeki görevini ayır: “yavaş yavaş yürüdü” sözünde zarf görevi vardır. Kalıp anlamı yorumlarken öğeleri tek tek sözlük anlamında toplamak yerine bütünün cümlede hangi durumu karşıladığını belirle.'
  ], 'Atasözü-deyim-ikileme tablosunda öğüt, kalıplaşma ve kuruluş ölçütlerini ayrı sütunlar olarak oku.', '“İleri geri konuştu.” ifadesindeki ikileme nasıl kurulmuştur?', 'Zıt anlamlı iki sözcükle kurulmuştur. Cümlede konuşmanın biçimini belirlediği için zarf görevindedir.');
  patch('tur-03', 'Cümlede Anlam 3', [19,20,21], [
    'Cümlenin taşıdığı tutumu adlandırırken geleceğe yönelmiş bütün yargıları aynı sayma. Tasarı konuşanın yapmayı planladığı iştir; tahmin kanıt veya izlenimden hareketle bir sonucu öngörür; olasılık gerçekleşmenin kesin olmadığını bildirir. Ön yargı ise olay tamamlanmadan kesin hüküm vermedir. “Bulutlar yoğunlaştı, yağmur bekliyorum.” tahmine; “Bu çalışma kesinlikle başarısız olacak.” ifadesi gerekçesiz peşin hüküm bağlamında ön yargıya örnek olabilir.',
    'Pişmanlık yapılmış bir davranışın sonucuna üzülme, hayıflanma kaçırılan fırsata veya yapılmamış işe üzülmedir. Sitem kişinin kendisini üzen muhatabına kırgınlığını hissettirirken yakınma daha genel bir durumdan şikâyeti anlatabilir. Öneride bir yol gösterilir; eleştiride durum değerlendirilir. Aynı cümle birden fazla duygu taşıyabildiğinden sorunun hedeflediği ilişkiyi seç. Özellikle “keşke”, “bence”, “sanırım” gibi tek sözcüklere bakıp bütün anlamı otomatik sınıflandırma; yüklemin neyi olmuş, olası veya amaçlanan gösterdiğini incele.'
  ], '19–21. sayfalardaki kavramları gelecek/geçmiş ve tutum/gerçekleşme ölçütleriyle eşleştir.', '“Keşke bu fırsat elimdeyken kursa yazılsaydım.” cümlesinde hangi duygu vardır?', 'Hayıflanma baskındır; yapılmamış bir iş ve değerlendirilmemiş fırsat nedeniyle üzüntü dile getiriliyor.');
  patch('tur-04', 'Paragrafta Anlam 1', [22,23,24,25], [
    'Öykülemede zaman içinde ilerleyen olaylar, betimlemede ise bir varlığın veya mekânın görünüşü öne çıkar. “Kapıyı açtı, merdiveni çıktı.” eylem akışı kurar; “Dar merdivenin duvarları nemliydi.” aynı yerdeki ayrıntıyı canlandırır. Bir paragrafta bu iki biçim birlikte bulunabilir; baskın anlatım sorulduğunda parçanın hangi amaçla kurulduğuna bakılır. Hareket bildiren bir sözcüğün varlığı tek başına bütün metni öyküleme yapmaz.',
    'Açıklama okura bilgi kazandırmayı, tartışma bir görüşü savunup karşı görüşü değiştirmeyi amaçlar. Tanımlama, örneklendirme, karşılaştırma, tanık gösterme ve sayısal veri kullanma ise bu amaçları destekleyen düşünceyi geliştirme yollarıdır. Kavramın ne olduğunu söylemek tanımlama, somut bir örneği sunmak örneklendirmedir. Bir uzmanın yalnız adının geçmesi tanık gösterme sayılmaz; savunulan düşünceyi destekleyen görüşünün aktarılması gerekir. Anlatım biçimi ile destekleme tekniğini aynı sınıflandırma düzeyi sanma.'
  ], '22–25. sayfalarda anlatım amaçlarını ve düşünceyi geliştiren araçları ayrı başlıklar altında izle.', '“Bazıları müzeyi gereksiz buluyor; oysa kent belleği bu mekânlar olmadan korunamaz.” hangi anlatım amacını taşır?', 'Tartışma amacı taşır; karşı görüş belirtilip ona karşı bir yargı savunuluyor.');
  const expressionNotes = [
    'Açıklık anlamın tek ve anlaşılır olmasıdır; duruluk gereksiz sözcüklerden arınmayı, yalınlık süssüz anlatımı belirtir. Bu özellikler yakın görünse de aynı değildir. “Onu kardeşinden çok sever.” cümlesinde karşılaştırmanın iki yorumu açıklığı bozar. “Geri iade etti.” sözünde gereksiz tekrar duruluğa aykırıdır. Sanatlı ama kolay anlaşılan bir cümle açık olabilir; söz sanatlarının bulunması otomatik anlam bulanıklığı yaratmaz.',
    'Akıcılık okuyuşu kesintiye uğratmayan ses ve söz dizimine; tutarlılık yargıların birbiriyle çelişmemesine dayanır. Özgünlük başkasını taklit etmeyen söyleyiş, özlülük az sözle yoğun anlam, doğallık yapmacıksız anlatımdır. Bir metnin kısa olması tek başına özlü olduğunu kanıtlamaz; anlam yoğunluğu gerekir. Soruda özelliği seçerken kusurlu cümlede hangi işlem yapılınca sorun çözülüyor diye düşün: sözcük silmek duruluğa, belirsiz karşılaştırmayı açmak açıklığa, çelişen yargıyı düzeltmek tutarlılığa işaret eder.'
  ];
  patch('tur-04', 'Paragrafta Anlam 2', [26,27,28,29,30], expressionNotes, '26–30. sayfalarda her anlatım özelliğini karşıt kusuruyla eşleştir; kısa olmak ile özlü olmayı ayır.', '“Bu işi bizzat kendim yaptım.” sözündeki sorun hangi özellikle ilgilidir?', 'Durulukla ilgilidir. “Bizzat” ve “kendim” aynı vurguyu gereksiz biçimde yineler.');
  patch('tur-06', 'Paragrafta Anlam 2', [26,27,28,29,30], [
    'Anlatım biçimi metnin ne yaptığını, anlatım özelliği bunu nasıl bir dille yaptığını gösterir. Açıklayıcı bir paragraf açık ve akıcı olabileceği gibi gereksiz tekrarlarla duruluktan da uzaklaşabilir. Bu nedenle betimleme, öyküleme gibi biçim adlarıyla yalınlık, özgünlük gibi nitelikleri aynı seçenek mantığıyla karıştırma. Kaynaktaki açıklık örneklerinde bir cümlenin birden fazla yoruma izin vermesi temel kusurdur.',
    'Bir paragrafı değerlendirirken her niteliğe ayrı kanıt ara. Yalınlık için süslü söyleyişin azlığı, duruluk için çıkarılınca anlamı değişmeyen sözlerin yokluğu, tutarlılık için yargıların uyumu gerekir. Özgün bir düşünce karmaşık kurulabilir; doğallık ile sıradanlık da aynı değildir. “Sonuç önemlidir.” deyip ardından “Sonucun hiçbir değeri yoktur.” demek gerekçeli bir bakış değişimi sunulmadıkça tutarsızlık oluşturur. Nitelikleri genel bir beğeni sözü gibi değil, metindeki somut dil ve anlam ilişkileriyle açıkla.'
  ], 'Aynı kaynak sayfalarını bu kez anlatım biçimiyle anlatım niteliğinin farkını görmek için kullan.', 'Söz sanatı içeren bir metin mutlaka kapalı mıdır?', 'Hayır. Yalınlığı az olabilir ama anlamı tek ve anlaşılır kurulmuşsa açık olabilir.');
  patch('tur-08', 'Yazım Kuralları 3', [50,51,52,53,54], [
    'Birleşik sözcükte bitişik veya ayrı yazım yalnız iki sözcüğün yan yana gelmesine göre belirlenmez; kalıplaşma, anlam değişmesi ve ses olayı gibi ölçütler birlikte değerlendirilir. Yardımcı eylemle kurulan yapılarda ses düşmesi veya türemesi varsa “hissetmek”, “kaybolmak” gibi bitişik yazım görülür; “yardım etmek” ayrı yazılır. Her “etmek” li yapıyı aynı biçimde yazmak bu farkı siler. Pekiştirmeler bitişik, ikilemeler genel olarak ayrı yazılır.',
    'Bağlaç olan de ve ki ile ek olan biçimleri görevlerinden ayır. “Ben de geldim.” sözünde de çıkarılınca temel yargı kalır; “evde” de bulunma anlamı taşıyan ek vardır. Soru eki mı ayrı yazılır, kendisinden sonra gelen ekler ona bağlanır: “gelecek misin”. Büyük harf, kısaltma ve sayı kurallarında özel adın tamamını ve ekin görevini incele. Bir yazım sorusunu ses benzerliğiyle değil sözcüğün cümledeki yapısıyla çöz.'
  ], '50–54. sayfalardaki birleşik sözcük ve ayrı yazılan yapı örneklerinde ses olayı ile görev ayrımına bak.', '“Seninde fikrini öğrenelim.” nasıl düzeltilir?', '“Senin de fikrini öğrenelim.” Bağlaç de ayrı yazılır; “senin” sözcüğündeki ilgi eki kendi üzerinde kalır.');
  patch('tur-09', 'Noktalama İşaretleri 3', [63,64,65,66], [
    'Noktalama işaretinin görevi cümlenin sözdizimine ve aktarılan bilginin türüne bağlıdır. Tırnak doğrudan aktarılan sözü veya özel olarak vurgulanan bir kullanımı sınırlar; yay ayraç cümlenin akışına ek açıklama yerleştirir. Ayraç içindeki açıklama çıkarıldığında temel cümle yapısı çoğunlukla sürer. Kısa çizgi ile uzun çizgi görev bakımından ayrıdır; konuşma satırındaki çizgiyi sözcükleri bağlayan kısa çizgiyle karıştırma.',
    'Kesme işareti bütün özel ad görünümlü yapılarda aynı biçimde kullanılmaz. Kişi ve yer adlarına gelen çekim ekleri ayrılırken kurum adlarına gelen ekler ve özel addan türetilmiş sözcüklerdeki ekler için ayrı kurallar vardır. Noktalama seçerken önce alıntının nerede başlayıp bittiğini ve ekin hangi ada bağlandığını belirle. İşareti yalnız okurken nefes alma yerine koyma; bir virgülün varlığı iki bağımsız sözün, bir kesmenin varlığı ise yazım kuralının sonucudur.'
  ], '63–66. sayfalarda tırnak, ayraç, çizgi ve kesmenin farklı kullanım yerlerini karşılaştır.', '“Türk Dil Kurumu’na” yazımı kaynak kuralına göre nasıl düzeltilir?', '“Türk Dil Kurumuna” yazılır. Kurum ve kuruluş adlarına gelen ekler kesmeyle ayrılmaz.');
  patch('tur-11', 'İsim', [76,77,78], [
    'İsim varlık, kavram veya durumu karşılar; somut olması şart değildir. “Masa” somut, “sevinç” soyut addır. Özel-cins, tekil-çoğul-topluluk ayrımları farklı ölçütlerdir; bir ad aynı anda birden fazla sınıfa girer. “Ordu” çok bireyi topluca karşıladığı hâlde biçimce tekildir; “ordular” ayrıca çoğul eki almıştır. Sınıflandırmada anlamdaki çokluk ile sözcükteki çoğul ekini ayır.',
    'İsim çekim ekleri sözcüğün cümlede ilişkisini gösterir. Hâl ekleri yönelme, bulunma, ayrılma ve belirtili nesne ilişkisi kurabilir; iyelik eki aitliği bildirir. “Kitabım” daki m birinci tekil iyelik, “kitabı” ndaki ı ise bağlama göre belirtme veya üçüncü tekil iyelik olabilir. Ekin yüzey biçimi aynı diye görevini aynı sayma. “Onun kitabı masada.” ile “Kitabı aldım.” cümlelerinde bağlılık ve nesne sorularını ayrı sorarak işlevi belirlersin.'
  ], '76–78. sayfalarda ad türlerini anlam ölçütlerine; ekleri kurdukları cümle ilişkilerine göre ayır.', '“Takım sahaya çıktı.” cümlesindeki takım çoğul isim midir?', 'Topluluk adıdır ve biçimce tekildir. Birden fazla kişiyi karşılaması, çoğul eki aldığı anlamına gelmez.');
  patch('tur-15', 'Fiilde Yapı', [103,104], [
    'Basit fiil yapım eki almamış fiildir; çok sayıda çekim eki taşıması onu türemiş yapmaz. “Geliyorduk” zaman ve kişi ekleriyle çekimlenmiştir ama kökü yeni bir sözlük anlamı kazanmamıştır. Türemiş fiilde ise isimden veya fiilden yeni eylem oluşturan yapım eki bulunur: “temizlemek” te temiz sıfatından eylem yapılır. Önce kökü belirleyip ekin yeni sözcük mü yoksa çekim mi oluşturduğunu sorgula.',
    'Birleşik fiiller yardımcı eylemle, kurallı birleşme veya anlamca kaynaşmayla oluşabilir. Yeterlik, tezlik, sürerlik ve yaklaşma anlamlarının hangi birleşik fiil kuruluşuyla verildiğini incele; örneğin “yapabilmek” yeterlik, “yapıvermek” tezlik taşır. Anlamca kaynaşmış yapılarda bütünün anlamı tek tek sözcüklerin toplamını aşabilir. Birleşik fiil olmak her zaman bitişik yazılmak demek değildir; “yardım etmek” ayrı yazıldığı hâlde birleşik fiildir. Yapı sınıflandırmasıyla yazım sınıflandırmasını ayrı tut.'
  ], '103–104. sayfalarda yapım/çekim eki ayrımını ve birleşik fiilin kuruluş yollarını izle.', '“Gözleyebiliyordum.” fiilini yalnız sonundaki kişi ekine bakarak basit sayabilir miyiz?', 'Hayır. Kök, yapım ekleri ve yeterlik birleşmesi incelenmelidir; çekim eklerinin sayısı tek başına yapı türünü belirlemez.');
  patch('tar-03', 'Avrasya’da İlk Türk İzleri - Coğrafya ile Oluşan Yaşam Tarzı', [14,15,16,17], [
    'Kaynağın kültür merkezleri tablosu, yazılı devlet tarihinden önceki yaşamı arkeolojik buluntularla tanımayı amaçlar. Bir mezardaki silah, at koşumu veya maden eşya üretim tekniği ve geçim hakkında veri sağlar; tek bir buluntudan bütün toplumsal yapıyı çıkarmak mümkün değildir. Anav, Afanesyevo, Andronova ve Karasuk gibi adlar buluntu alanlarını belirtir. Bu kültürleri devlet adıyla veya bugünkü ülke sınırlarıyla özdeşleştirme.',
    'Bozkırda geniş otlaklara bağlı hayvancılık, mevsimlik hareketliliği ve atlı yaşamı destekler. Hareketli yaşam taşınabilir eşya, savaşta hızlı birlikler ve farklı bölgelerle temas gibi sonuçlar doğurabilir. Ancak bütün Türk topluluklarının her dönemde aynı geçim biçimini taşıdığını söylemek aşırı genellemedir. Türk ve Türkiye adlarının kaynaklara göre farklı anlam ve coğrafyalarda kullanılması da kavramların tarih içindeki değişimini gösterir. Bugünkü siyasal anlamı eski bir metne doğrudan taşıma.'
  ], '14. sayfadaki ad ve coğrafya bilgilerini 15–17. sayfaların kültür merkezleri ve bozkır yaşamıyla birlikte değerlendir.', 'Bir kültür bölgesinde at koşumları bulunması doğrudan yerleşik tarım yapıldığını gösterir mi?', 'Hayır. At kullanımı için kanıt sağlar; tarım için ürün, alet veya yerleşme gibi ek bulgular gerekir.');
  patch('tar-03', 'Kavimler Göçü', [23,24,25,26,27], [
    'Kavimler Göçü tek bir topluluğun yalnız kendi yerini değiştirmesinden daha geniş bir zincirleme harekettir. Batıya ilerleyen Hunların baskısı, başka toplulukların da Roma topraklarına yönelmesini hızlandırır. Bu nedenle nedenler, göçün hareketi ve uzun vadeli sonuçlar ayrı aşamalardır. Bir topluluğun yerinden edilmesi başkasının göçünü tetikleyebilir; haritadaki oklar bu etkileşimi gösterir.',
    'Kaynak Avrupa’daki siyasal parçalanma, yeni krallıklar ve Hun varlığını birlikte işler. Roma’nın dönüşümünü yalnız bir göç tarihine indirmek yerine askerî baskı, yönetim ve nüfus hareketlerinin birleşik etkisini düşün. Avrupa Hun Devleti ile daha sonraki Türk topluluklarının etkinlikleri de aynı devletin kesintisiz devamı değildir. Kronolojide önce-sonra ilişkisi kurmak sebep-sonucu destekler; sonradan gerçekleşen bir olay önceki hareketin nedeni olamaz. Coğrafi sonuç ile kültürel etkileşimi ayrı maddelerde toplamak yorum yapmayı kolaylaştırır.'
  ], '23. sayfanın göç haritasında zinciri izle; sonraki sayfalarda Avrupa Hunları ve sonuçları karşılaştır.', 'Hunların hareketinin başka kavimleri batıya yöneltmesi hangi göç özelliğini gösterir?', 'Göçlerin birbirini tetikleyebildiğini ve etkilerinin ilk hareket eden toplulukla sınırlı kalmadığını gösterir.');
  patch('tar-04', 'Emeviler (661-750)', [32,33], [
    'Emeviler döneminde halifeliğin hanedan içinde aktarılması, Dört Halife dönemindeki seçim anlayışından farklı bir siyasal düzen oluşturur. Muaviye’nin oğlu Yezid’i işaret etmesi bu değişimin örneğidir. Kerbela olayı siyasal rekabet ile dinî ayrışmanın iç içe geçişini gösterir; olayı yalnız bir fetih başarısı veya toprak kaybı gibi sınıflandırmak yanlış olur.',
    'Mevali politikası Arap olmayan Müslümanların ayrı tutulmasıyla ilgilidir. Kaynak bu politikanın toplumsal hoşnutsuzluğu artırması ve İslamiyet’in bazı topluluklar arasında yayılmasını zorlaştırması üzerinde durur. Buna karşılık İspanya’ya geçiş askerî-coğrafi genişlemeyi gösterir. Şam merkezli Emevi Devleti’nin 750’de sona ermesiyle Endülüs’te kurulan Emevi yönetimini aynı tarih ve merkezde sanma. Bir hanedan adının yeniden kullanılması iki siyasi oluşumun bütün özelliklerinin aynı olduğu anlamına gelmez.'
  ], '32. sayfada saltanat ve mevali ilişkisini;33. sayfada Şam Emevileri ile Endülüs ayrımını izle.', 'Mevali uygulaması neden İslam dininin evrenselliğiyle gerilim oluşturur?', 'Müslümanları etnik kökene göre farklı statülere ayırdığı için; ortak din aidiyetine rağmen ayrıcalık üretir.');
  patch('tar-05', 'İslamiyet’in Türk Devlet ve Toplum Yapısına Etkisi', [40,41,42,43], [
    'Türklerin İslamiyet’i kabulü önceki devlet geleneğinin bütün unsurlarını bir anda ortadan kaldırmaz. Hanedan, töre ve yönetim deneyimi İslam hukuk ve kurumlarıyla etkileşerek yeni bir sentez oluşturur. Karahanlılar ile Gaznelileri incelerken kuruluş coğrafyası, halkın yapısı ve resmî dil gibi ölçütleri ayrı ele al. Birinin Türkçe kullanımını sürdürmesi, bütün Türk-İslam devletlerinin aynı dil politikasına sahip olduğunu göstermez.',
    'Sultan, divan, medrese ve vakıf gibi kavramlar farklı işlev taşır. Divan yönetim işlerini, medrese eğitimi, vakıf belirli gelirlerin sosyal hizmete tahsisini açıklar. Gazneli Mahmut’un Abbasi halifesiyle ilişkisi siyasal güç ile dinî meşruiyet arasındaki bağı gösterir. Edebî eserleri yalnız yazar adıyla değil yazıldığı dil ve taşıdığı siyaset/ahlak düşüncesiyle eşleştir. Kültürel süreklilik ile yeni kurum kazanımı aynı süreçte birlikte bulunabilir.'
  ], '40. sayfada iki devleti,41–43. sayfalarda egemenlik, kurum ve kültür dönüşümünü karşılaştır.', 'İslamiyet’in kabulünden sonra töre unsurlarının sürmesi nasıl yorumlanır?', 'Yeni inancın benimsenmesiyle önceki siyasal-kültürel birikimin birlikte var olabildiğini, dönüşümün bütünüyle kopuş olmadığını gösterir.');
  patch('tar-06', 'Türklerin Anadolu’ya Yerleşme Süreci - Anadolu’ya Türk Göçleri ve Bu Göçlerin Sosyokültürel Etkileri', [47,48], [
    'Anadolu’ya ilk akınlar ile kalıcı yerleşme aynı aşama değildir. Bir askerî birliğin bölgeden geçmesi sürekli nüfus, kurum ve üretim düzeni kurulduğunu tek başına göstermez. Kaynak Hun ve Sabar akınlarını daha sonraki Oğuz-Türkmen hareketlerinden bu nedenle kronolojik olarak ayırır. “Türkiye” adının farklı zamanlarda farklı coğrafyaları karşılaması da bugünkü kullanımın geçmişe aynen taşınamayacağını gösterir.',
    'Çağrı Bey’in keşif seferleri, Pasinler ve Malazgirt gibi gelişmeler Anadolu’ya yönelişin askerî boyutunu; göç eden toplulukların köy, şehir ve kurumlar kurması sosyokültürel boyutunu oluşturur. Yerleşme bir tek savaş gününde tamamlanan sonuç değil süreçtir. Savaş güvenli geçişi ve siyasal imkânı artırabilir; nüfus hareketi, ekonomi ve kültürel etkileşim bunu kalıcılığa dönüştürür. Haritada güzergâhı, metinde ise hareketin amaç ve sonucunu birlikte izle.'
  ], '47. sayfanın ilk akınlarını 48. sayfanın Oğuzlar ve Selçuklu seferleriyle zaman sırasına koy.', 'Bir akın kaydı tek başına bölgenin kesin yurt edinildiğini kanıtlar mı?', 'Hayır. Kalıcı yerleşme için sürekli nüfus, siyasal egemenlik ve kurumlaşma gibi ek göstergeler gerekir.');
  patch('tar-06', 'Hilal ve Haç Mücadelesi', [53,54], [
    'Haçlı seferlerinin dinî söylemi, bütün nedenlerinin yalnız dinî olduğu anlamına gelmez. Kutsal yerler, Bizans’ın yardım talebi, ticaret yolları ve toprak kazanma isteği farklı neden gruplarıdır. Aynı olayın dinî, siyasi ve ekonomik etkenleri birlikte olabilir. Seferleri sınıflandırırken gerekçenin hangi alanı etkilediğini somutlaştır: ticaret yolu ekonomik, bir devletin yardım çağrısı siyasidir.',
    'Birinci seferde İznik’in kaybı ve Selçuklu merkezinin Konya’ya taşınması Anadolu’daki doğrudan sonucu gösterir. Kudüs’ün 1187’de Selahaddin Eyyubi tarafından geri alınması sonraki seferin hazırlayıcı gelişmesidir. Dördüncü seferin İstanbul’a yönelmesi ise ilan edilen amaçla fiilî sonucun farklılaşabileceğini gösterir. Farklı seferlerin neden ve sonuçlarını tek torbada toplama; bir sonuç daha sonraki seferin nedeni olabilir. Avrupa’daki toplumsal ve ticari değişimleri de tek bir anlık savaş sonucu olarak yorumlama.'
  ], '53. sayfanın neden sınıflarını 54. sayfadaki farklı seferlerin hedef ve sonuçlarıyla eşleştir.', 'Dördüncü seferin İstanbul’u hedef alması hangi basit genellemeyi bozar?', 'Bütün seferlerin yalnız Kudüs’e yöneldiği ve ilan edilen dinî hedefin her zaman fiilî hedefle aynı kaldığı genellemesini.');
  patch('tar-06', 'Moğol İstilası ve Anadolu', [55,56,57], [
    'Moğol baskısı Anadolu’ya yeni Türkmen göçlerini artırırken Türkiye Selçuklu yönetimini de güvenlik tedbirlerine yöneltir. Yassıçemen sonrasında Harzemşahların zayıflaması, Moğollar ile Selçuklular arasındaki tampon gücün ortadan kalkması bakımından önemlidir. Aynı olayın bir cephede askerî başarı sayılması uzun vadede her zaman stratejik avantaj getirdiği anlamına gelmez.',
    'Babaî isyanının bastırılmasındaki güçlük merkezî otoritenin zayıflığını görünür kılar.1243 Kösedağ yenilgisi sonrasında Moğol nüfuzu artar; Selçuklu merkezinin denetimi zayıfladıkça uçlarda yeni beyliklerin etkinliği genişler. İkinci beylikler dönemi bu siyasal parçalanmayla ilişkilidir. Beyliklerin oluşmasını yalnız nüfus artışıyla açıklama; iktidar boşluğu, yerel askerî güç ve coğrafi konum da etkilidir. Sonuçları siyasi bağımlılık, göç ve kültürel yapılanma olarak ayırmak aynı gelişmenin farklı etkilerini daha doğru gösterir.'
  ], '55–57. sayfalarda Yassıçemen, Babaî isyanı, Kösedağ ve beyliklerin güçlenmesini neden-sonuç zincirine yerleştir.', 'Tampon devletin ortadan kalkması neden komşu devlet için yeni tehlike yaratabilir?', 'Dış güçle arasındaki dolaylı sınır kaybolur; askerî baskıyla doğrudan karşılaşma ihtimali artar.');
  patch('tar-07', 'Anadolu’da Türk Siyasi Birliğini Sağlama Çabaları', [62,63,64], [
    'Anadolu Türk siyasi birliği, aynı bölgede farklı hanedanların yönettiği Türk beyliklerinin tek otorite altında toplanmasını anlatır. Bu süreçte fetih kadar akrabalık, satın alma ve himaye gibi yöntemler de kullanılır. Her toprak kazanımını aynı savaş yöntemiyle açıklamak kaynaktaki strateji çeşitliliğini kaçırır. Rumeli genişlemesiyle Anadolu’daki beylik siyaseti farklı meşruiyet ve rakip güç koşullarında yürütülür.',
    'Ankara Savaşı sonrasında beyliklerin yeniden ortaya çıkması, kurulmuş birliğin geri çevrilebilir olduğunu gösterir. Fetret Devri’nde hanedan üyeleri arasındaki mücadele merkezî otoriteyi zayıflatır. Yeniden toparlanma yalnız yeni toprak almak değil, vergi ve asker toplama yetkisinin tekrar merkezde birleştirilmesidir. Haritada sınırın büyümesini siyasal birliğin tek ölçüsü sayma; bir bölgenin merkeze bağlılığı da önemlidir. Osmanlıların doğu rakiplerinin beyliklerle ilişkilerini göz önünde tutması, yerel mücadelelerin daha geniş güç dengeleriyle bağlantısını gösterir.'
  ], '62–64. sayfalarda birliğe katma yöntemlerini ve Ankara Savaşı sonrası değişimi karşılaştır.', 'Bir beyliğin evlilik yoluyla toprak devretmesi doğrudan askerî fetih midir?', 'Hayır. Siyasal birliği destekleyen diplomatik/akrabalık temelli bir toprak kazanımıdır.');
  patch('tar-07', 'Devletleşme Sürecinde Savaşçılar ve Askerler', [65,66,67], [
    'Osmanlı askerî yapısı uç savaşçıları çevresindeki ilk birliklerden daha sürekli ve uzmanlaşmış örgütlere doğru gelişir. Alplar ve gaziler, yaya-müsellem birlikleri ve kapıkulları aynı dönemde aynı görev tanımıyla ortaya çıkmış tek birlik değildir. Devletin alanı ve seferleri büyüdükçe düzenli insan gücü, eğitim ve finansman ihtiyacı artar. Kurumsallaşmayı bu ihtiyaçla ilişkilendirmek kuruluş tarihlerini anlamlı kılar.',
    'Tımarda köylünün işlediği toprağın mülkiyeti değil, belirli vergi gelirlerini toplama yetkisi hizmet karşılığında tahsis edilir. Sipahi bu gelirle asker yetiştirir; üretimin sürmesi askerî düzenin finansmanına bağlanır. Kapıkulları ise merkez ordusudur ve maaş sistemiyle ilişkilidir. Pençik savaş esirleri, devşirme belirli kurallarla toplanan çocuklar üzerinden insan kaynağı sağlar; iki kavramı eş anlamlı kullanma. Bir ordunun sayısı kadar hangi kaynakla beslendiği ve kime bağlı olduğu merkeziyetçilik yorumunu belirler.'
  ], '65. sayfada ilk birlikleri,66. sayfada tımarı,67. sayfada yeniçeri ve insan kaynağını karşılaştır.', 'Tımar verilmesi toprağın özel mülk olarak sipahiye satılması mıdır?', 'Hayır. Temel ilişki hizmet karşılığında vergi gelirinin tahsisidir; toprak mülkiyetiyle gelir hakkı ayrılır.');
  patch('tar-07', 'Anadolu’nun Mutasavvıfları - Yönetici Sınıf - Sosyal ve Kültürel Faaliyetler', [68,69,70,71,72], [
    'Kaynak askerî fetihlerle kültürel yerleşmenin farklı fakat birbirini destekleyen süreçler olduğunu gösterir. Mutasavvıflar,âlimler ve eğitim kurumları dinî-ahlaki düşüncenin aktarımında; tekke, zaviye ve vakıflar toplumsal dayanışmada etkili olur. Yunus Emre’nin Türkçe söyleyişi yalnız dil tercihi değil, düşüncenin geniş kitlelere ulaşması bakımından da değerlendirilebilir. Ancak farklı düşünürlerin öğretilerini tek bir kişinin görüşü gibi birleştirme.',
    'Yönetici sınıfta seyfiye askerî-idari, ilmiye eğitim-hukuk-din, kalemiye mali ve bürokratik işleri temsil eder. Unvanı ezberlemekten önce görevi sınıflandır:vergi kaydı kalemiye, mahkeme ilmiye ile ilişkilidir. Şehirlerde cami, han, bedesten ve imaret gibi yapılar farklı ihtiyaçları karşılar; birlikte imar ve ekonomik canlanmayı destekler. Sanat alanındaki ahşap, çini ve taş işçiliği de bu kurumların mekânsal biçimine yansır. Böylece kültür bölümü yalnız eser adı değil, toplumda üstlenilen işlevler üzerinden okunur.'
  ], '68–72. sayfalarda düşünür, meslek grubu ve yapı adlarını yerine getirdikleri işleve göre eşleştir.', 'Bir kadının adli karar vermesi hangi yönetici sınıfın görevidir?', 'İlmiye sınıfının; adalet ve hukuk işleri bu sınıfın görevleri arasındadır.');
  patch('tar-08', 'Dünyanın Muhteşem Gücü Osmanlı', [78,79,80], [
    'Kanuni döneminin Avrupa siyasetinde Belgrad, Mohaç ve Viyana aynı olayın farklı adları değildir; her biri ayrı hedef ve sonuç taşır. Belgrad Orta Avrupa’ya yönelişte stratejik kapı, Mohaç Macar siyasal düzenini değiştiren savaş olarak okunur.1533 İstanbul Antlaşması’ndaki protokol hükümleri ise askerî başarının diplomatik statüye nasıl yansıdığını gösterir. Antlaşma maddesinden çıkarım yaparken hangi tarafın kime eşit sayıldığını dikkatle belirle.',
    'Doğu siyasetinde Safevilerle mücadele ve 1555 Amasya Antlaşması, batı cephesiyle eşzamanlı farklı bir güç alanını gösterir. Bir padişah döneminin güçlü olması bütün cephelerde bütün seferlerin kesin sonuçlandığı anlamına gelmez. Kronolojiyi batı/doğu başlıklarına bölerek karşılaştırmak olayları karıştırmayı azaltır. Toprak değişimi, sınır güvenliği ve siyasi üstünlük farklı sonuç türleridir. Aynı yüzyıldaki deniz ticaretinin önemini de kara fetihlerinden bağımsız düşünme; genişleyen devlet birden fazla stratejik alanı yönetmek zorundadır.'
  ], '78–80. sayfalarda batı ve doğu gelişmelerini, askerî sonuç ile diplomatik statü ayrımıyla oku.', 'Bir hükümdarın başka devletin hükümdarı yerine vezirine denk sayılması neye işaret eder?', 'Protokolde eşitlik bulunmadığına ve bir tarafın siyasi üstünlük iddiasına işaret eder; yalnız ekonomik veri değildir.');
  patch('tar-08', 'Stratejik Siyaset ve Dünya Gücü Olan Osmanlı Devleti', [81,82,83,84], [
    'Osmanlıların rakipleri aynı nedenle karşı karşıya geldiği tek bir blok değildir. Avusturya ile Orta Avrupa, Safevilerle doğu sınırı, Venedik ve Portekizle deniz ticareti gibi farklı çıkar alanları bulunur. Fransa ile yakınlaşma, Habsburg baskısını dengelemek ve Avrupa’daki karşıt birlikleri zayıflatmak bakımından değerlendirilir. Dış politikayı yalnız din ortaklığı veya ayrılığıyla açıklamak bu ilişkileri anlamaya yetmez.',
    'Kapitülasyon ticari ayrıcalık tanınmasıdır; verildiği dönemde diplomatik ve ticari amaçlar taşıyabilir. Daha sonraki ekonomik etkilerini ilk verildiği dönemin bütün koşullarıyla özdeşleştirme. Coğrafi keşiflerle yeni deniz yollarının açılması ticaret güzergâhlarının önemini değiştirir; Hint Deniz Seferleri bu rekabetle bağlantılıdır. Açık denize uygun gemi, yerel destek ve mesafe gibi koşullar askerî sonucu etkiler. Bir seferin belirli kıyılarda kazanım sağlaması bütün okyanus ticaretini kontrol ettiği anlamına gelmez.'
  ], '81–84. sayfalarda her rakibi coğrafi çıkar alanıyla; kapitülasyon ve deniz seferlerini ticaret yollarıyla bağla.', 'Osmanlı-Fransız yakınlaşması dış politikada hangi etkenin önemini gösterir?', 'Ortak rakibe karşı çıkar ve güç dengesi hesabının; devlet ilişkileri yalnız din aidiyetiyle belirlenmez.');
  patch('tar-08', 'Saray ve Şehir Kültürü - Gelenekler Işığında Devlet İdaresi', [85,86,87], [
    'Saray yalnız hükümdarın evi değil, yönetim, eğitim ve hizmet örgütlenmesinin merkezidir. Topkapı’nın bölümleri günlük yaşamla devlet görevlerinin farklı işlevlerini taşır. Enderun seçilmiş kişileri devlet hizmetine hazırlayan eğitim alanıdır; medreseyle aynı kurum değildir. Bir kişinin hangi eğitim yolundan geldiği, yer aldığı yönetim görevleriyle ilişkilendirilir. Şehir kültüründe ise ticaret, zanaat ve vakıf yapıları birlikte değerlendirilir.',
    'Veraset düzenindeki değişiklikler hanedan içi rekabeti ve merkezî otoriteyi ilgilendirir. “Ülke hanedanın ortak malıdır” anlayışından yetkiyi daha dar merkezde toplama yönündeki düzenlemeleri süreklilik ve değişim içinde oku. Fatih’in kanunnamesiyle I. Ahmet dönemindeki ekber-erşed yaklaşımını aynı tarihte sanma. Bir uygulamanın amacı taht mücadelesini azaltmak olabilir; bu, uygulamanın bütün dönemlerde sorunsuz işlediğini kanıtlamaz. Kanunun normu ile tarihsel sonuç arasındaki farkı koru.'
  ], '85–87. sayfalarda saray eğitimiyle veraset düzenini farklı yönetim sorunları olarak karşılaştır.', 'Enderun ile medreseyi aynı eğitim kurumu saymak neden yanlıştır?', 'Öğrenci kaynakları, eğitim amaçları ve hazırladıkları görev alanları farklıdır; her ikisinin eğitim vermesi aynı kurum olduklarını göstermez.');
  patch('tar-09', 'Osmanlı Devleti’nde Millet Sistemi - Fethettiği Yerlerdeki Kültürel Değişim', [88,89,90], [
    'Millet sisteminde temel sınıflandırma bugünkü anlamıyla etnik ulus değil, din ve mezhep aidiyetidir. Farklı topluluklar bazı dinî, eğitsel ve kişisel hukuk işlerini kendi kurumlarıyla yürütürken siyasi egemenlik Osmanlı merkezine aittir. Bu düzeni bağımsız devletler federasyonu gibi yorumlamak doğru değildir. Cizye gibi yükümlülükler de statü farklılıklarıyla ilişkilidir; modern vatandaşlık eşitliği kavramını geçmişe aynen taşımamak gerekir.',
    'Mahalle sosyal dayanışma ve gündelik denetim alanıdır; çarşı, ibadet yeri ve vakıf yapıları şehir yaşamını örgütler. Fetih sonrası kültürel değişim yalnız önceki bütün unsurların silinmesi değil, göç, imar ve karşılıklı etkileşimle yeni bileşimlerin oluşmasıdır. Mutfak, kıyafet ve kahvehane örnekleri farklı alanlardaki gündelik hayatı gösterir. Bir giysi veya yemek örneğinden bütün topluluğun siyasal statüsünü çıkarmak yerine, metnin gerçekten hangi sınıflandırma ölçütünü verdiğine bak.'
  ], '88. sayfada din-mezhep esasını;89–90. sayfalarda mahalle, şehir ve gündelik yaşamı ayrı düzeylerde incele.', 'Millet sistemi bugünkü etnik ulus sınıflandırmasıyla aynı mıdır?', 'Hayır. Kaynakta din ve mezhep aidiyeti temel alınır; modern ulus kavramı farklı bir tarihsel bağlama aittir.');
  patch('tar-09', 'Uzun Savaşlardan Diplomasiye', [94,95,96,97], [
    'Uzun süreli savaşlar askerî kayıp yanında hazine, üretim ve iç güvenlik üzerinde yük oluşturur. Osmanlıların aynı dönemde Avusturya, Safeviler ve iç isyanlarla uğraşması bir cephedeki kararların ötekilerle bağlantısını gösterir.1606 Zitvatorok Antlaşması’nda Avusturya hükümdarının protokol statüsünün değişmesi,1533’teki üstünlük düzeninden farklı bir diplomatik aşamadır.',
    'Antlaşmaları yalnız kazanıldı/kaybedildi etiketiyle okumak yerine sınır, vergi, unvan ve temsil maddelerini ayır. 1699 tarihli Karlofça gibi geniş toprak kayıplarına yol açan gelişmelerle arabuluculuk ve ittifak arayışlarının artması dış politikada diplomasinin ağırlığını gösterir. Mütekabiliyet karşılıklılık demektir; tek taraflı ayrıcalıkla aynı değildir. Bir antlaşmada eşit protokol benimsenmesi bütün askerî ve ekonomik güçlerin eşitlendiğini kanıtlamaz; çıkarım verilen maddeyle sınırlı kurulmalıdır.'
  ], '94–97. sayfalarda savaşın mali yükünü ve antlaşmaların protokol/sınır hükümlerini birlikte oku.', 'Zitvatorok’taki protokol değişimi neden yalnız toprak bilgisi değildir?', 'Tarafların diplomatik statü ve üstünlük ilişkisini değiştirir; bir sınır maddesi olmadan da siyasi anlam taşır.');
  patch('tar-10', 'Okyanusların Önem Kazanması', [98,99], [
    'Coğrafi keşiflerle okyanuslara açılan ticaret, Avrupa devletlerinin deniz gücü ve sömürge rekabetini büyütür. Ticaret şirketleri uzak bölgelerde sermaye, taşıma ve ticari denetimi örgütler. Sömürgecilik yalnız mal alışverişi değildir; başka bölgelerin kaynak ve insan gücünün eşitsiz, çoğu zaman zorlayıcı biçimde kontrolünü içerir. Hammadde ve pazar arayışları bu ağların ekonomik yönüdür.',
    'Kadırga kürek gücü ve çevikliğiyle, kal­yon yelken ve büyük gövdesiyle farklı deniz koşullarına uygundur. Akdeniz’de etkili bir gemi modelinin okyanusta aynı üstünlüğü taşımaması teknolojinin çevreyle ilişkisini gösterir. Denizcilik stratejisindeki değişim yalnız araç değişimi değil, uzun yol, ikmal ve top gücü ihtiyacının dönüşümüdür. Ticaret yollarının ağırlığının değişmesi eski merkezleri bir anda tamamen işlevsiz yapmaz; rekabet ve gelir kaynaklarını yeniden düzenler. Bu nedenle “önem kaybı” ile“tamamen sona erme” ifadelerini ayır.'
  ], '98. sayfada sömürge ve şirket ağlarını;99. sayfada kadırga-kalyon farkını ekonomik hedeflerle bağla.', 'Kadırgadan kalyona yönelme yalnız kültürel bir moda olarak açıklanabilir mi?', 'Hayır. Açık deniz koşulları, menzil, taşıma ve savaş gücü gibi teknik-stratejik ihtiyaçlarla ilişkilidir.');
  patch('tar-10', 'Fetihlerden Savunmaya', [100,101,102], [
    'XVIII. yüzyılda Osmanlı dış politikasında kaybedilen yerleri geri alma, mevcut toprakları koruma ve rakip güçleri dengeleme amaçları birlikte görülür. Prut, Pasarofça, Belgrad ve Küçük Kaynarca aynı sonuçları doğuran antlaşmalar değildir. Birinde kazanım sağlanması bütün yüzyıl boyunca genişleme olduğu anlamına gelmez. Antlaşmayı hazırlayan savaş ile antlaşmanın siyasi, ekonomik ve dinî hükümlerini ayrı başlıklarda oku.',
    'Rusya’nın Karadeniz ve sıcak denizler hedefi kuzeydeki baskıyı artırırken Avusturya ve Venedik ilişkileri farklı cepheler oluşturur.1774 Küçük Kaynarca’da Kırım’ın bağımsızlığı, Osmanlı ile Rusya arasındaki bağlılık düzenini değiştirir; daha sonraki Rus ilhakı ise ayrı olaydır. Kaynakta “ilk” ve“son” gibi nitelemeler hangi alan için kullanılıyor dikkat et. Bir savaşın nedeni olan sınır güvenliği sorunu ile sonucunda doğan ticari hak aynı şey değildir. Savunmaya yönelişi tek bir savaşla değil, birbirini izleyen güç değişimleriyle açıkla.'
  ], '100–102. sayfalarda antlaşmaları tarih, savaş ve ayrı hüküm sütunlarıyla karşılaştır.', 'Kırım’ın bağımsız olması ile Rusya tarafından ilhak edilmesi aynı aşama mıdır?', 'Hayır. Bağımsızlık önceki bağlılığın değişmesi; ilhak daha sonra başka devletin egemenliğine alınmasıdır.');
  patch('tar-10', 'Osmanlı Devleti’nde Değişim', [107,108], [
    'Dünya ticaretine yeni kaynakların ve kıymetli madenlerin katılması, fiyatları ve üretim dengelerini etkiler. Osmanlı ekonomisini yalnız iç yönetim hatalarıyla açıklamak bu dış bağlantıları dışarıda bırakır. Kapitülasyonların sürekli hâle gelmesiyle yabancı ticari ayrıcalıkların zaman içindeki konumu değişir. İlk veriliş amacı ile uzun vadeli sonuçların farklı olabileceğini koru; bir kurum değişmeden aynı etkiyi üretmek zorunda değildir.',
    'Asker sayısının artırılması daha çok maaş, donanım ve nakit ihtiyacı doğurur. Tımar gelirinin asker yetiştirmeyle bağı zayıfladığında merkez farklı finansman yollarına yönelir. İltizamda vergi toplama hakkı belirli süre ve bedelle mültezime bırakılır; malikânede sürenin uzaması yeni bir farklılıktır. Bunları toprağın özel mülk olarak satılmasıyla özdeşleştirme. Kaynak, ordu ve vergi düzeni arasındaki karşılıklı bağı gösterir:askerî ihtiyaç mali değişimi, gelir yöntemi de taşradaki güç ilişkilerini etkiler.'
  ], '107. sayfanın dış ticaret/fiyat değişimini 108. sayfanın ordu ve vergi toplama düzeniyle bağla.', 'Yeniçeri sayısını artırmak neden tek başına askerî başarıyı garanti etmez?', 'Eğitim ve disiplinin yanında hazineye ek yük getirir; nicelik artışı örgütlenme ve finansman sorunlarını otomatik çözmez.');
  patch('tar-10', 'Osmanlı Devleti’nde İsyanlar ve Düzeni Koruma Çalışmaları', [109,110,111,112,113], [
    'İstanbul’daki yeniçeri ayaklanmalarıyla Anadolu’daki Celali hareketlerini aynı neden ve sonuç listesine indirgeme. Maaş, para ayarı, iktidar rekabeti ve taşradaki üretim-vergi sorunları farklı ağırlıklar taşıyabilir. Merkezî otoritenin zayıflaması hem isyanların nedeni hem bunların sonucunda derinleşen bir durum olabilir. Nedenselliğin iki yönlü olması olayları tek basamaklı ezberlememeyi gerektirir.',
    'Layiha ve risaleler sorunları teşhis edip çözüm öneren raporlardır; çoğu klasik düzenin yeniden işletilmesine vurgu yapar. Lâle Devri’nin elçilik, kütüphane ve basım faaliyetleri ise bilgiye erişim ve dış dünyayı tanıma yönünü gösterir. Osmanlı ülkesindeki ilk matbaalarla Müslümanlarca işletilen İbrahim Müteferrika matbaasını ayır:ilk ifadesinin kapsamı farklıdır. Bir yeniliğin kültürel olması siyasi koşullardan bağımsız olduğu anlamına gelmez; bilgi üretimi, yönetim ve toplumsal değişim birbirine bağlanır.'
  ], '109–113. sayfalarda isyan türü, ıslahat raporu ve bilgi üretimini ayrı fakat ilişkili başlıklar olarak izle.', 'Müteferrika matbaası Osmanlı topraklarındaki ilk matbaa mıdır?', 'Hayır. Daha önce gayrimüslim toplulukların matbaaları vardır; buradaki yenilik Müslümanların matbaa faaliyetinin başlamasıdır.');
  patch('tar-10', 'Osmanlı Devleti’nde Modern Orduya Geçiş', [116,117], [
    'Modern orduya geçiş yalnız birlik adını değiştirmek değildir; eğitim, silah, komuta, finansman ve asker toplama düzeninin yeniden kurulmasını içerir. III. Selim’in Nizam-ı Cedit girişimi yeni bir ordu ve bunu destekleyen mali düzenle ilişkilidir. Mevcut askerî grupların çıkarlarıyla çatışma yeniliğin uygulanmasını zorlaştırabilir. Bir reformun amaçlanması onun kesintisiz ve tam başarılı olduğu anlamına gelmez.',
    'II. Mahmut döneminde 1826’da Yeniçeri Ocağı kaldırıldıktan sonra Asâkir-i Mansûre-i Muhammediye kurulur. Yeni düzenin personel ve subay ihtiyacı askerî okulların önemini artırır. Zorunlu askerlik ise nüfus kaydı, vatandaşlık ve merkezi yönetimin doğrudan insan gücüne ulaşmasıyla bağlantılıdır. Nizam-ı Cedit ile Asâkir-i Mansûre’yi aynı padişahın aynı birlik adı sanma. Kurumların tarih sırası, önceki deneyimin sonraki düzenlemeye nasıl örnek olduğunun anlaşılmasını sağlar.'
  ], '116–117. sayfalarda reformu başlatan hükümdarı, kurulan birliği ve personel kaynağını eşleştir.', 'Yeni ordu kurulması eğitim kurumlarını neden etkiler?', 'Düzenli subay, mühendis ve teknik uzman gereksinimi yeni okul ve programları gerekli kılar.');
  patch('tar-10', 'XIX. Yüzyılda Sosyal Hayattaki Değişimler', [118,119,120,121], [
    'Demir yolu malları ve askerleri daha hızlı taşırken telgraf haberin yolculuk süresini azaltır. İkisi farklı teknolojilerdir ama merkezin taşraya ulaşmasını ve kararlarını uygulamasını kolaylaştırabilir. Hatların yabancı şirketlerce kurulması sermaye ve imtiyaz ilişkisini de gündeme getirir; teknolojik kazanımla ekonomik bağımlılık aynı süreçte birlikte bulunabilir. Bu nedenle ulaşım yeniliğini yalnız kültürel etkileşim başlığına kapatma.',
    'Modern okulların açılması askerî ve idari uzman ihtiyacıyla bağlantılıdır. Medreselerin yanında yeni okulların sürmesi eğitimde farklı yolların birlikte var olmasına yol açar. Yabancı okulların amacı ve yönetimi devlet okullarıyla aynı değildir. Hastane, Dârülaceze ve emeklilik düzenlemeleri sosyal yardımın kurumsallaşmasını gösterir. Fakat bir yardım kurumunun varlığı bütün nüfusun aynı kapsamda korunmuş olduğunu kanıtlamaz. Kaynakta her kurumun hangi ihtiyaca cevap verdiğini ve kimleri kapsadığını ayrı belirle.'
  ], '118–121. sayfalarda ulaşım, haberleşme, eğitim ve sosyal yardımı işlevlerine göre karşılaştır.', 'Telgrafın yaygınlaşması merkezî otoriteyi nasıl güçlendirebilir?', 'Merkezin taşradan daha hızlı bilgi almasını ve talimat göndermesini sağlayarak yönetim süresini kısaltır.');
  patch('tar-10', 'Osmanlı Devleti’ne Yönelik Tehditler-I', [122,123,124,125], [
    'XIX. yüzyıldaki Osmanlı sorunlarında Rusya’nın genişleme hedefleri, Avrupa güç dengesi ve milliyetçi hareketler birlikte etkilidir. Şark Meselesi büyük güçlerin Osmanlı topraklarının geleceğine ilişkin rekabetini anlatan tarihsel bir çerçevedir; her devletin bütün tarihlerde aynı politikayı izlediği anlamına gelmez. Aynı güç bir dönemde toprak bütünlüğünü desteklerken başka çıkar koşulunda paylaşımı destekleyebilir.',
    'Yunan bağımsızlığı, Kırım Savaşı ve 93 Harbi farklı kronolojik aşamalardır. Kırım Savaşı’nda İngiltere ve Fransa’nın Rusya’ya karşı Osmanlı yanında yer alması denge hesabını gösterir; kalıcı dostluk sonucu çıkarılmaz.1856 Paris düzenlemesiyle 1878 Berlin sonuçlarını aynı antlaşma listesinde karıştırma. Bir antlaşmanın toprak, hukuki statü ve ekonomik hükümleri ayrı sonuçlar doğurur. Balkanlardaki ayaklanmalarda iç toplumsal taleplerle dış devlet desteğinin birlikte bulunması da tek nedenli açıklamayı yetersiz kılar.'
  ], '122–125. sayfalarda Rusya hedefleri, Balkan hareketleri ve büyük güçlerin değişen tutumunu zaman sırasıyla izle.', 'Bir devletin Osmanlı toprak bütünlüğünü desteklemesi sürekli dostluk kanıtı mıdır?', 'Hayır. O anki güç dengesi ve rakibin genişlemesini sınırlama çıkarıyla ilişkili olabilir.');
  patch('tar-11', 'Osmanlı Devleti’nde Darbeler', [130,131], [
    'Darbe, yönetimin olağan siyasal usuller dışında zor kullanılarak değiştirilmesidir; anayasa veya seçimle gerçekleşen her iktidar değişimi aynı kavramla anlatılmaz. Meşrutiyet yanlısı düşüncenin gelişimi ile belirli bir darbe girişiminin örgütlenmesi ayrı düzeylerdir. Yeni Osmanlıların siyasi beklentileri dönemin özgürlük ve parlamento tartışmalarıyla ilişkilendirilir; bir grubun bütün üyelerinin bütün yöntemlerde aynı davrandığı varsayılmaz.',
    '31 Mart Olayı adındaki tarih Rûmî takvime aittir; Miladi takvimde 13 Nisan 1909 olması iki ayrı olay olduğu anlamına gelmez. Hareket Ordusu’nun müdahalesi veII.Abdülhamid’in tahttan indirilmesi olayın sonuçlarıdır.1913 Bâbıâli Baskını ise farklı şartlarda gerçekleşir ve İttihat ve Terakki’nin iktidar konumunu güçlendirir. Neden, eylem ve sonuçları aynı cümlede ayırarak yazmak tarihleri karıştırmayı önler. Anayasal düzeni savunmakla uygulanan yöntemin anayasal olması mantıksal olarak aynı iddia değildir.'
  ], '130–131. sayfalarda her girişimin tarihi, hedef aldığı yönetim ve sonucunu ayrı tut; takvim farkına dikkat et.', '31 Mart ile 13 Nisan 1909 neden aynı olay için kullanılır?', 'Rûmî ve Miladi takvimlerin farklı tarih göstermesi nedeniyle; iki adlandırma iki farklı olayı belirtmez.');
  patch('tar-11', 'Osmanlı Devleti’ne Yönelik Tehditler-II', [132,133], [
    'Kavalalı Mehmet Ali Paşa’nın Mısır’da güçlenmesi, merkezin bir valiye karşı askeri-siyasi denetim sorunu yaşamasıdır. Mora isyanında merkez bu güçten yardım isterken daha sonra talepleriyle çatışır. İç bir yönetim meselesinin Rusya ve diğer Avrupa devletlerinin müdahalesine açılması, Osmanlı sorunlarının uluslararasılaşmasını gösterir. Her dış desteğin karşılıksız olduğunu varsaymak antlaşma sonuçlarını kaçırır.',
    'Hünkâr İskelesi ve 1841 Londra Boğazlar Sözleşmesi aynı düzenleme değildir. İlki Rusya ile yakınlaşma bağlamında, ikincisi boğazların uluslararası bir statü kazanması bakımından okunur. Osmanlıların geçiş düzenini tek başına belirleme imkânının sınırlanması egemenlik yetkisiyle ilgilidir. Almanya ve İtalya’nın siyasi birliklerini kurmasıyla rekabet ve bloklaşma değişir; aynı Avrupa tablosu bütün yüzyıla sabitlenemez. İç isyan, dış borç ve ittifaklar birbirini etkileyebilir fakat her birinin kendi yakın nedeni ayrıca gösterilmelidir.'
  ], '132–133. sayfalarda Mısır sorununun boğazlar ve Avrupa dengesiyle nasıl bağlandığını izle.', 'Bir iç sorunun çözümüne dış devletlerin katılması neyi gösterir?', 'Sorunun uluslararası bir nitelik kazanabildiğini ve merkezin karar alanının dış güç dengelerinden etkilenebildiğini.');
  patch('tar-11', 'Osmanlıda Sanayileşme Çabaları', [134,135,136,137], [
    'Sanayi üretimiyle rekabette yalnız fabrika sayısı değil, sermaye, teknoloji, ulaşım, iş gücü ve pazar koşulları belirleyicidir. Küçük atölyelerle makineleşmiş seri üretimin maliyet yapıları farklıdır.1838 Balta Limanı Antlaşması ticari ayrıcalıklar ve pazar erişimi üzerinden yerli üretimin rekabet koşullarını etkiler. Bir antlaşmanın siyasi destek arayışıyla yapılması ekonomik sonuçlarının önemsiz olduğu anlamına gelmez.',
    'Dış borçların çevrilmesinde güçlük,1881 Düyûn-ı Umûmiye İdaresi’ne bazı vergi gelirlerinin bırakılmasıyla bağlantılıdır. Bu idare bir sanayi tesisi değil, alacakların tahsilini örgütleyen mali denetim yapısıdır. Millî iktisat girişimleri yerli girişimci, banka ve üretimi destekleme hedefi taşır. Hedef ile gerçekleşen sonucu ayır; bir politikanın ilanı bütün dış bağımlılığın sona erdiğini kanıtlamaz. Ekonomik değişimde dış ticaret, borç ve üretimi aynı neden zincirinde düşünmek tek kavrama bütün anlamı yüklemeyi önler.'
  ], '134–137. sayfalarda üretim rekabeti, ticaret düzeni, borç tahsili ve millî iktisadı ayrı işlevlerle eşleştir.', 'Düyûn-ı Umûmiye neden ekonomik bağımsızlık tartışmasıyla ilişkilidir?', 'Belirli vergi gelirlerinin tahsili üzerinde alacaklıların etkisini kurumsallaştırdığı için; mali karar alanını sınırlar.');
  patch('tar-11', 'XIX ve XX. Yüzyılda Osmanlı Nüfusu-Metropoller Salgınlar ve Kamuoyu', [138,139,140,141], [
    'Toprak kaybı ile nüfus kaybı aynı ölçüm değildir. Bir bölgenin imparatorluktan ayrılması toplam sayıyı değiştirirken o bölgeden Anadolu’ya göç, başka yerlerde nüfus yoğunluğunu artırabilir. Bu nedenle bir grafikte azalma görüldüğünde yalnız doğum ve ölümden sonuç çıkarılmaz; sınır ve göç etkileri de incelenir. Zorunlu göçler barınma, istihdam ve sağlık ihtiyacını birlikte doğurur.',
    'Modern şehirde ulaşım, belediye ve altyapı hizmetleri kalabalık nüfusun sorunlarına yanıt verir. Karantina, aşı ve sağlık kuruluşları salgınla mücadelede farklı araçlardır; karantina hastalığı önleyici tedbir olup tedaviyle aynı görevde değildir. Basın-yayın ve okuryazarlığın artması ortak sorunların tartışılmasını hızlandırır; bu kamuoyunun oluşmasıyla bağlantılıdır. Gazetede bir görüş yayımlanması bütün halkın aynı görüşü benimsediğini kanıtlamaz. İletişim imkânı ile görüş birliğini ayrı düşün; kamusal tartışma farklı kanaatleri de görünür kılar.'
  ], '138–141. sayfalarda sınır-göç, nüfus-şehir ve basın-kamuoyu bağlarını ayrı çizgilerle kur.', 'Anadolu’da nüfus artarken imparatorluğun toplam nüfusu azalabilir mi?', 'Evet. Toprak kaybıyla dışarıda kalan nüfus ve Anadolu’ya yönelen göç farklı ölçeklerde ters değişimler doğurabilir.');
  patch('tar-11', 'Mustafa Kemal’in Lider Olarak Yetişmesinde Etkili Koşullar', [142,143], [
    'Mustafa Kemal’in yetişmesini tek bir okul veya şehirle açıklamak yerine eğitim, okuma, arkadaş çevresi ve görev deneyimini birlikte incele. Askerî okullar mesleki disiplin ve komuta bilgisi kazandırırken edebiyat ve tarih ilgisi düşünsel ufku genişletir. Farklı düşünürlerden etkilenmek onların bütün görüşlerini aynen benimsemek demek değildir; metin hangi etkiyi belirtiyorsa çıkarımı o alanla sınırla.',
    'Selanik’in liman, demir yolu ve çok kültürlü yapısı farklı fikirlerle karşılaşmaya; Manastır’ın askerî ve siyasi ortamı ülke sorunlarını gözlemlemeye imkân verir. İstanbul’da devlet merkezini görmek ile yabancı bir şehirde görev yaparak dış kurumları tanımak farklı deneyimlerdir. Bir özellikten doğrudan gelecekteki bütün başarıları zorunlu sonuç olarak çıkarma. Tarihsel açıklama, mevcut koşulların hangi bilgi, beceri veya farkındalığı desteklediğini göstermelidir. Okul sırasını ve şehirlerin özelliklerini bu işlevlerle eşleştirmek kuru yer adı ezberini anlamlı ilişkiye dönüştürür.'
  ], '142–143. sayfalarda okul ve görev yerlerini, orada kazanılan düşünsel/mesleki deneyimle eşleştir.', 'Selanik’in çok kültürlü yapısından hangi sınırlı çıkarım yapılabilir?', 'Farklı topluluk ve düşüncelerle karşılaşma imkânı sunduğu; tek başına kişinin bütün görüşlerini belirlediği söylenemez.');
  patch('tar-11', '20. Yüzyıl Başlarında Osmanlı Devleti', [144,145,146,147,148], [
    'Osmanlıcılık, İslamcılık, Türkçülük ve Batıcılık devletin sorunlarına farklı çözüm öncelikleri getirir. Osmanlıcılık ortak vatandaşlıkla bütünlüğü, İslamcılık dinî dayanışmayı, Türkçülük millî bilinci, Batıcılık Batı kurum ve tekniklerinden yararlanmayı öne çıkarır. Aynı kişinin birden çok düşünceden etkilenmesi mümkün olduğundan akımları birbirinden tamamen kopuk kutular sayma. Bir metni ana çözüm önerisinden hareketle sınıflandır.',
    'Trablusgarp’ta İtalya’nın sömürge arayışı, Balkan savaşlarında milliyetçilik ve paylaşım rekabeti farklı yakın nedenlerdir. I. Balkan Savaşı’nın sonucuyla Balkan devletlerinin kendi arasında çatıştığı II. savaşın sonucunu ayır; Edirne’nin geri alınması ikinci aşamayla bağlantılıdır. Ekonomide dış borç, yabancı denetim ve millî iktisat arayışları savaş koşullarıyla iç içedir. Bir cephedeki yerel başarı bütün savaşın diplomatik sonucunu otomatik değiştirmez; Uşi ve Balkan antlaşmalarını bu ayrımla oku.'
  ], '144–148. sayfalarda düşünce akımlarıyla somut savaşların neden-sonuçlarını farklı tablolar hâlinde karşılaştır.', 'Balkan devletlerinin kendi aralarındaki paylaşım çatışması Osmanlıya hangi imkânı verdi?', 'II. Balkan Savaşı sırasında Edirne ve çevresini geri alma fırsatı sağladı; bu ilk savaşın sonucu değildir.');
  patch('tar-13', 'Millî Mücadele’ye Hazırlık Dönemi-I', [157,158,159], [
    'İzmir’in 15 Mayıs 1919’da işgali, yerel bir askerî olayın ülke genelinde tepki ve örgütlenmeyi hızlandırmasına örnektir. Protesto mitingleri, silahlı direniş ve raporlarla dış dünyaya durumu anlatma farklı mücadele araçlarıdır. Kuvay-ı Millîye merkezî bir düzenli ordudan önce ortaya çıkan gönüllü yerel kuvvetlerdir; aynı adla anılmaları hepsinin tek komutaya bağlı olduğu anlamına gelmez.',
    'Bu birlikler ilerleyişi yavaşlatıp zaman kazandırırken düzensiz komuta ve kaynak temini sorunları da taşır. Düzenli orduya geçiş onları değersiz saymak değil, mücadelenin ihtiyacına uygun yeni örgütlenme kurmaktır. Amiral Bristol gibi inceleme raporları, işgali gerekçelendiren iddiaların bağımsız gözlemle sorgulanabildiğini gösterir. Bir raporun haklılığı desteklemesi işgallerin kendiliğinden bittiğini kanıtlamaz; diplomatik kanıt ile askerî sonuç ayrı şeylerdir. Kaynaktaki olay sırası, toplumsal tepkinin örgütlü direnişe dönüşümünü görünür kılar.'
  ], '157–159. sayfalarda işgal, toplumsal tepki, Kuvay-ı Millîye ve raporların farklı işlevlerini izle.', 'Kuvay-ı Millîye neden düzenli orduyla aynı örgüt değildir?', 'Yerel, gönüllü ve dağınık komuta yapısındadır; düzenli orduda ortak hiyerarşi, disiplin ve planlı lojistik bulunur.');
  patch('tar-13', 'Büyük Millet Meclisi’nin Açılması - Sevr Antlaşması', [164,165,166], [
    'İstanbul’un işgali ve Mebusan Meclisinin kapatılması temsil ve yönetim boşluğunu büyütür.23 Nisan 1920’de Ankara’da meclisin açılması millî iradeye dayanan yeni bir siyasal merkezin oluşmasıdır. Yasama ve yürütmenin mecliste birleşmesi olağanüstü mücadele koşullarındaki meclis hükûmeti anlayışını gösterir. Farklı görüşlere rağmen bağımsızlık hedefinde birleşilmesi bütün üyelerin her konuda aynı düşündüğü anlamına gelmez.',
    'Meclise karşı ayaklanmalar yalnız dış cephe değil, iç otorite ve meşruiyet sorunu da bulunduğunu gösterir. Sevr’in sınır, askerlik, mali denetim ve boğazlarla ilgili hükümleri bağımsız karar alanını daraltır. Ankara meclisinin bu düzenlemeyi reddetmesiyle İstanbul yönetiminin yaklaşımını aynı tutum gibi sunma. Antlaşmanın imzalanması, yürürlüğe girme usulü ve fiilen uygulanması ayrı tarihsel aşamalardır. Kaynakta harita sınırlarıyla maddelerin hangi egemenlik alanını etkilediğini birlikte incelemek paylaşımın yalnız toprakla sınırlı olmadığını gösterir.'
  ], '164–166. sayfalarda meclisin yetkileri ve Sevr hükümlerinin egemenlik alanlarına etkisini karşılaştır.', 'Bir antlaşmada mali denetimin dış güçlere verilmesi neden bağımsızlıkla ilişkilidir?', 'Devletin gelir ve harcamaları üzerinde kendi başına karar verme yetkisini sınırladığı için; yalnız sınır değişimi bağımsızlığı etkilemez.');
  patch('tar-13', 'Doğu, Güney ve Batı Cepheleri', [167,168,169,170,171,172,173], [
    'Cepheleri karşılaşılan güç, mücadeleyi yürüten örgüt ve sonuç antlaşmasıyla eşleştir. Doğuda Kazım Karabekir komutasındaki düzenli birlikler ve Gümrü, Güneyde şehir direnişleri ve Fransa ile Ankara Antlaşması öne çıkar. Batıda düzenli orduya geçiş ortak komuta ve lojistik ihtiyacıyla ilişkilidir. Bir cephenin kapanması insan ve teçhizatın başka cepheye aktarılmasına imkân vererek mücadelenin kaynaklarını değiştirir.',
    'İnönü savaşları düzenli ordunun ve meclisin saygınlığını desteklerken Kütahya-Eskişehir geri çekilmesi yeni savunma hazırlığına yol açar. Sakarya, Yunan taarruzunun durdurulması ve diplomatik sonuçları; Büyük Taarruz ise kesin askerî sonuca yöneliş bakımından ayrılır.1921 Anayasası, Londra Konferansı ve Kars-Ankara antlaşmaları savaşların arasındaki siyasi boyuttur. Askerî başarı diplomatik görüşme gücünü artırabilir ama her antlaşmayı sonrasındaki savaşın nedeni sayma. Önce hangi olayın önce geldiğini ve hangi devletin tutum değiştirdiğini belirle; aynı zaferin iç otorite ve dış tanınma üzerindeki etkilerini ayrı göster.'
  ], '167–173. sayfalarda her cepheyi örgüt ve antlaşmayla; Batı savaşlarını askerî-diplomatik sonuçlarıyla eşleştir.', 'Doğu cephesinin kapanmasının Batı cephesine etkisi ne olabilir?', 'Asker ve donanımın Batıya aktarılmasını kolaylaştırır; cepheler kaynak ve strateji bakımından birbirine bağlıdır.');
  patch('cog-01', 'Coğrafyanın Konusu ve Bölümleri', [11,12,13], [
    'Coğrafya yalnız yer adı öğrenmek değil, olayların nerede, neden orada ve birbirleriyle nasıl ilişkili olduğunu incelemektir. Fiziki coğrafya doğal sistemleri; beşerî coğrafya insan faaliyetlerinin mekânsal düzenini ele alır. Aynı barajın su rejimini değiştirmesi hidrografya, yerleşmeleri etkilemesi beşerî coğrafya yönüdür. Bu alanlar farklı soru sorar fakat gerçek dünyada birbirinden kopuk değildir.',
    'Jeomorfoloji yer şekillerini, klimatoloji iklimi, biyocoğrafya canlıların dağılışını inceler. Coğrafyanın yararlandığı bilimle kendi alt dalını karıştırma:jeoloji kayaç ve yer yapısı bilgisi sağlar; coğrafi soru bu veriyi dağılış ve insan-çevre ilişkisine taşır. Tarihsel gelişim bölümünde harita ve betimleme çalışmalarından açıklayıcı yöntemlere ilerleyiş görülür. Bir bilim insanının katkısını yalnız ad eşleştirmesiyle değil, nasıl bir gözlem, harita veya yöntem geliştirdiğiyle ilişkilendir. Böylece coğrafi bilgi bir konum listesi değil, mekânsal açıklama ağı olur.'
  ], '11–13. sayfalarda alt dalı, incelediği olayı ve yararlandığı bilimi ayrı sütunlar olarak oku.', 'Bir limanın çevresinde sanayi tesislerinin yoğunlaşmasını incelemek hangi ana alana girer?', 'Beşerî coğrafyaya; sanayi ve ulaşımın mekânsal ilişkisi inceleniyor. Doğal kıyı koşulları ise bu açıklamaya fiziki veri sağlayabilir.');
  patch('cog-03', 'Koordinat Sistemi', [19,20], [
    'Enlem bir noktanın Ekvator’a göre kuzey-güney açısal konumunu, boylam Greenwich’e göre doğu-batı konumunu belirtir. Paraleller tam çemberdir ve kutuplara gidildikçe küçülür; meridyenler kutuplarda birleşen yarım çemberlerdir. Bu nedenle aynı boylam farkının yüzeydeki uzunluğu her enlemde aynı değildir. Bir derece enlem farkının meridyen üzerindeki uzaklığı yaklaşık 111 km olarak kullanılır.',
    'Boylam farkı yerel saatle ilişkilidir:Dünya 24 saatte 360°döndüğünden 1°fark 4 dakikadır. Doğudaki yerin yerel saati ileridedir; resmî ortak saat ise siyasi tercihle belirlenebilir. Enlem Güneş ışınının geliş açısı, gölge ve mevsimsel gündüz farkları üzerinde etkili olur; boylam bunların doğrudan nedeni değildir. Aynı enlemdeki yerlerin bütün iklim özellikleri eşit olmaz; yükselti, denizellik ve akıntılar da etkilidir. Mutlak konumdan yapılabilecek çıkarımla göreli konum etkisini bu ayrımla sınırla.'
  ], '19–20. sayfalarda paralel/meridyen geometrisini ve enlem/boylam sonuçlarını ayrı eşleştir.', '30°Doğu ile 45°Doğu arasında yerel saat farkı kaçtır ve hangisi ileridir?', '15·4=60 dakika;45°Doğu daha doğuda olduğu için bir saat ileridir. Bu, resmî saat dilimi bilgisi değildir.');
  patch('cog-08', 'Dünya’nın Tektonik Oluşumu ve Jeolojik Zamanlar', [60,61], [
    'Yer kabuğu, manto ve çekirdek kimyasal yapılarına göre temel katmanlardır. Levhaların oluşturduğu litosfer ise yer kabuğuyla üst mantonun en dıştaki katı bölümünü birlikte içerir; yalnız kabuğun başka adı olarak düşünülmemelidir. Levha hareketleri sıkışma, açılma ve yanal yer değiştirme gibi farklı sınır davranışları doğurur. Bunlar dağ oluşumu, deprem ve volkanizmanın dağılışını açıklamada kullanılır.',
    'Jeolojik zamanlar insanlık tarihinin yüzyıllarıyla aynı ölçekte değildir. Fosiller, kayaçlar ve tabakalar geçmiş çevrelerin izlerini taşır; jeolojik takvim bu farklılıklarla kurulur. Türkiye’nin genç tektonik hareketlerden etkilenmesi bütün arazisinin aynı yaşta olduğu anlamına gelmez; eski masiflerle genç oluşumlar birlikte bulunur. Afrika, Arabistan ve Avrasya levhaları arasındaki konum dağ kuşakları ve aktif kırıklarla ilişkilidir. Bir yerde eski kayaç bulunması o bölgede güncel tektonik hareketin olamayacağını göstermez; malzemenin yaşıyla hareketin tarihi farklı bilgilerdir.'
  ], '60. sayfada iç yapı ve levhayı,61. sayfada jeolojik zaman ile Türkiye’de farklı yaşlı arazilerin birlikteliğini karşılaştır.', 'Türkiye’de eski masiflerin bulunması genç tektonik hareketlerle çelişir mi?', 'Hayır. Eski kayaç kütleleri daha sonraki hareketlerden etkilenebilir; arazinin malzeme yaşıyla hareketin yaşı aynı olmak zorunda değildir.');
  patch('cog-09', 'Dış Kuvvetler (Karstik Şekiller, Dalgalar, Akıntılar)', [73,74,75,76], [
    'Bu kaynak sayfaları Türkiye’de iç ve dış kuvvetlerin birlikte oluşturduğu yer şekillerini ele alır. Sıkışmayla kıvrılan tabakalar Kuzey Anadolu ve Toros kuşaklarıyla; Batı Anadolu’daki kırılmalar horst-graben düzeniyle ilişkilendirilir. İç kuvvetler yükselti ve ana yapıyı oluştururken akarsu gibi dış etkenler bu yüzeyi aşındırır ve taşınan malzemeyi biriktirir. Bir dağın varlığı ile üzerindeki vadinin oluşumu aynı süreç değildir.',
    'Karstik şekiller çözünebilen kayaçlarda suyun kimyasal etkisiyle gelişir. Lapya, dolin, uvala ve polye farklı ölçek ve oluşum örüntüleridir; her çukur alanı tek başına karst saymak doğru değildir. Traverten ise çözünmüş maddenin yeniden çökelmesine bağlı birikimdir. Kaynaktaki Türkiye örneklerini kayaç, iklim ve su ilişkisiyle eşleştir.76.sayfadaki dağ-plato örnekleri ana şekillerin dağılışını tamamlar; yalnız yer adı ezberlemek yerine her örneğin kıvrım, kırık, volkanizma veya aşınma-birikimle ilişkisini göster.'
  ], '73. sayfada Türkiye’nin iç kuvvetlerini,74’te akarsu şekillerini,75’te karstı,76’da dağ ve platoları izle.', 'Bir vadinin bir dağ kuşağı içinde bulunması ikisinin aynı kuvvetle oluştuğunu gösterir mi?', 'Hayır. Dağ kuşağını tektonik hareketler, üzerindeki vadiyi akarsu aşındırması şekillendirmiş olabilir.');
  patch('cog-10', 'Türkiye’de Su Kaynakları', [81,82,83], [
    'Türkiye denizlerini karşılaştırırken sıcaklık, tuzluluk ve kıyı biçimini aynı nedene bağlama. Tuzluluğu buharlaşma, tatlı su girişi ve su alışverişi birlikte etkiler. Ege kıyılarının girintili yapısı kıyı uzunluğunu ve doğal limanları etkiler; bu durum deniz alanının büyüklüğüyle aynı ölçüm değildir. Göl ve akarsu kaynakları ise havzanın jeolojisi ve beslenmesiyle farklılaşır.',
    'Akarsu rejimi debinin yıl içindeki değişimidir; akış hızı veya toplam yıllık su miktarı değildir. Karla beslenen bir akarsuda ilkbahar erimesi yükseliş oluşturabilir. Eğimli ve genç arazide enerji potansiyeli artarken ulaşım güçleşebilir. Yer altı kaynaklarında karstik çözünme, fay hatları ve basınçlı akiferler farklı su çıkışları oluşturur. Sıcak suyun faylarla ilişkisi jeotermal kullanımını destekler; her kaynak suyu sıcak değildir. Kaynağı kullanan sektörle suyun oluşum mekanizmasını ayırmak doğru nedensellik kurar.'
  ], '81–83. sayfalarda deniz, akarsu, göl ve yer altı suyunu farklı beslenme ve kullanım koşullarıyla karşılaştır.', 'Bir akarsuyun rejiminin düzensiz olması ne demektir?', 'Debisinin yıl içinde belirgin değişmesi demektir; bu bilgi tek başına her yerde hızlı aktığını veya az su taşıdığını söylemez.');
  patch('cog-10', 'Dünyada ve Türkiye’de Bitkiler', [88,89,90,91], [
    'Bitki topluluklarının dağılışı sıcaklık, yağış ve bunların mevsimsel düzeniyle ilişkilidir. Yıl boyu sıcak-nemli ortam ormanı; uzun kurak dönem su kaybını azaltan uyumları destekler. Step ile çayırın ikisi de ot topluluğudur fakat nem ve boy özellikleri farklıdır. Endemik bitki doğal yayılışı belirli bir bölgeyle sınırlı olandır; bu kavram yalnız az sayıda bulunmak demek değildir. Kozmopolit ise geniş yayılışa işaret eder.',
    'Türkiye’de dağların yükseltisi, bakı ve denize göre konumu kısa mesafelerde farklı toplulukların oluşmasına yol açar. Karadeniz’in nemli ormanlarıyla iç kesimlerin bozkırları yalnız enlem farkıyla açıklanamaz. İnsan etkisiyle tahrip edilen ormanın yerini başka topluluklar alabilir; bugünkü örtü her zaman iklimin bozulmamış doğal sonucunu göstermez. Maki, orman ve yüksek dağ çayırlarını aynı yükselti basamağına yerleştirme. Haritada bitki dağılışını okurken iklimi, yer şekillerini ve insan müdahalesini birlikte sınamak daha doğru açıklama verir.'
  ], '88–91. sayfalarda topluluk türlerini iklim gereksinimiyle; Türkiye örneklerini yükselti, bakı ve tahriple eşleştir.', 'Bir bitkinin endemik olması yalnız sayısının az olduğunu mu gösterir?', 'Hayır. Temel ölçüt doğal yayılış alanının belirli bir coğrafyayla sınırlı olmasıdır; yerel bolluk başka bir bilgidir.');
  patch('cog-11', 'Türkiye Nüfusu', [99,100,101], [
    'Nüfus miktarı, nüfus artış hızı ve nüfus yoğunluğu farklı göstergelerdir. Artış hızının düşmesi nüfusun mutlaka azaldığı anlamına gelmez; hız hâlâ pozitifse sayı büyümeye devam eder. Aritmetik yoğunluk toplam nüfusun toplam alana bölümüdür; insanların her noktaya eşit yayıldığını söylemez. Kaynaktaki harita ve piramitler belirtilen geçmiş yıllara aittir; bugünün sayıları gibi okunmamalıdır.',
    'Dağılışta sanayi, ulaşım, tarım, turizm ve idari işlev gibi beşerî koşullar; engebe, iklim ve su gibi doğal koşullarla birleşir. Aynı yükseltiye sahip iki yer farklı ekonomik işlevler yüzünden farklı yoğunluk gösterebilir. Piramidin tabanı çocuk nüfusu, üst bölümü ileri yaşları anlatır; doğurganlık azalırken ortanca yaş yükselebilir. Çalışma çağındaki nüfus ile fiilen çalışan nüfus aynı değildir; öğrenci veya işsizler yaş grubunda bulunabilir. Her grafiğin yılını, ölçeğini ve hangi nüfus grubunu ölçtüğünü önce belirle.'
  ], '99–101. sayfalarda geçmiş yıl verilerini miktar, hız, yoğunluk ve yaş yapısı ayrımıyla değerlendir.', 'Artış hızı %2’den %1’e inerken nüfus azalmak zorunda mıdır?', 'Hayır. İki hız da pozitiftir; nüfus daha yavaş artıyor olabilir. Mutlak azalma için net değişimin negatif olması gerekir.');
  patch('cog-14', 'Şiddetli Rüzgârlar, Sel ve Taşkın, Çığ, Orman Yangınları, Salgın Hastalıklar', [117,118,119,120], [
    'Tehlikenin türüyle kaybı artıran koşulları ayır. Şiddetli yağış sel oluşturabilir; geçirimsiz yüzey, dere yatağında yapılaşma ve yetersiz drenaj zararı büyütebilir. Çığda kar birikimi, eğim ve kar tabakalarının dengesi; yangında kuru yanıcı örtü, tutuşma ve rüzgârın yayma etkisi önemlidir. Bütün afetleri yalnız iklimle açıklamak insanın yer seçimi ve hazırlığını dışarıda bırakır.',
    'Tropikal siklonlarla Türkiye’deki orta kuşak fırtınaları aynı oluşum ortamında gelişmez. Salgınlar biyolojik tehlikedir; yayılış ulaşım, nüfus ve sağlık altyapısıyla bağlantılı olabilir. Kaynaktaki tarihli afet harita ve istatistiklerini güncel toplam sanma. Afet yönetiminde risk azaltma ve hazırlık olay öncesini, müdahale ve iyileştirme olay anı/sonrasını kapsar. Bir yardım ekibi göndermek ile riskli alanda yapılaşmayı önlemek farklı aşamalardır. Coğrafi yorumda hem doğal süreci hem maruz kalma ve kırılganlığı belirtmek, benzer olayın neden farklı kayıp doğurduğunu açıklar.'
  ], '117–119. sayfalarda tehlike mekanizmasını, kayıp artırıcı koşulları ve afet yönetimi aşamalarını ayır;120.kapanış sayfasıdır.', 'Dere yatağında yapılaşmayı sınırlandırmak afet yönetiminin hangi yönüne girer?', 'Olay öncesi risk azaltmaya. Sel oluştuktan sonraki kurtarma müdahalesinden farklı bir aşamadır.');
  patch('cog-16', 'Doğal Çevrenin Kullanımı', [58,59], [
    'İnsan çevreden besin, su, enerji ve yapı malzemesi sağlar; aynı zamanda çevreyi tarım, baraj, yol ve yerleşmeyle değiştirir. Bu ilişki tek yönlü değildir:iklim ve yer şekilleri kullanım imkânlarını etkilerken teknoloji bazı sınırlamaları azaltabilir. Bir tünel dağın ulaşım engelini hafifletir ama doğal yapının bütün etkilerini ortadan kaldırmaz. Kullanımın yararıyla çevresel maliyeti aynı örnekte birlikte bulunabilir.',
    'Litosfere müdahale maden ve yol yapımı; hidrosfere müdahale su çekimi ve kirlenme; atmosfere müdahale emisyonlar; bitki örtüsü tahribi ise biyosferle ilişkilidir. Küreler bağlantılı olduğu için orman kaybı toprağın aşınmasını, su rejimini ve canlı ortamını birlikte etkileyebilir. Fosil yakıt kullanımında karbondioksit gibi sera gazlarıyla farklı kirleticileri aynı işlevde sanma. Sürdürülebilirlik kaynağı hiç kullanmamak değil, yenilenme kapasitesi ve sonraki kuşakların gereksinimlerini gözeten kullanım kurmaktır. Bir çevre sorununu bu bağlantılar üzerinden açıklamak tek bir belirtiye odaklanmayı önler.'
  ], '58–59. sayfalarda insan kullanımını litosfer, hidrosfer, atmosfer ve biyosfer etkilerine göre sınıflandır.', 'Orman tahribi yalnız biyosferi mi etkiler?', 'Hayır. Toprağın korunmasını azaltarak litosferde erozyonu, sızma-akış dengesini değiştirerek su sistemlerini de etkileyebilir.');
  patch('fel-01', 'Felsefenin İnsan ve Toplum Hayatı Üzerindeki Rolü', [14], [
    'Felsefenin bireysel işlevi hazır yanıtı kabul ettirmek değil, bir inanç veya kararın gerekçelerini görünür kılmaktır. “Herkes böyle yapıyor.” sözü bir davranışın yaygınlığını bildirir; doğru veya iyi olduğunu tek başına kanıtlamaz. Sorgulama bu iki iddia arasındaki farkı fark etmeyi sağlar. Kişinin değerlerini düşünmesi, başkalarının görüşlerini hiç dinlememesi değil, kendi kabulünün nedenlerini açıklayabilmesidir.',
    'Toplumsal düzeyde farklı görüşlerin gerekçeyle tartışılması önyargıların sorgulanmasına ve ortak yaşam ilkelerinin değerlendirilmesine katkı verir. Felsefi sorgulama her anlaşmazlığı otomatik ortadan kaldırmaz; anlaşmazlığın nereden doğduğunu açıklaştırabilir. Bilim, sanat ve siyasetle ilişkisi de bu kavramsal katkıdadır. Bir uygulamanın verimli olmasıyla adil olması aynı soru değildir. Kaynaktaki bireysel ve toplumsal işlevleri ayırırken eleştirel düşünmenin hem kişinin kararına hem ortak kurumların değerlendirilmesine uygulanabildiğini gör.'
  ], 'Bireysel ve toplumsal işlev tablolarında aynı sorgulama tutumunun iki farklı ölçekteki etkisini karşılaştır.', 'Bir düşüncenin çok kişi tarafından kabul edilmesi onun doğruluğunu tek başına kanıtlar mı?', 'Hayır. Yaygınlık toplumsal bir olgu, doğruluk ise iddianın gerekçe ve konusuyla ilişkisine dair değerlendirmedir.');
  patch('fel-01', 'Düşünme ve Akıl Yürütmeye İlişkin Kavramlar', [15,16,17], [
    'Önerme doğru veya yanlış değeri alabilen yargıdır; soru ve emir cümlesi bu görevde değildir. Argümanda öncüller bir sonucu desteklemek için kullanılır. Öncüllerin doğru olması ile sonucun onlardan geçerli biçimde çıkması ayrı ölçütlerdir. “Bütün kuşlar uçar; penguen kuştur; öyleyse penguen uçar.” biçim olarak tümdengelim düzenindedir fakat ilk öncül doğru değildir. Biçimsel geçerlilik içerik doğruluğunu otomatik sağlamaz.',
    'Tümdengelimde uygun biçimdeki doğru öncüller sonucu zorunlu kılar. Tümevarım gözlenen örneklerden genele gider; sonuç çoğunlukla olasılıklıdır. Analojide benzerlikten yeni bir benzerlik tahmin edilir; hangi özelliğin ilgili olduğu önemlidir. Tutarlılık önermelerin birbirini çürütmemesi, doğruluk ise iddianın konusuna uygunluğuyla ilgilidir. Birbiriyle uyumlu birkaç yanlış yargı tutarlı olabilir. Gerçeklik var olana, doğruluk ise o varlık hakkındaki yargıya yüklenir; masa gerçek olabilir, masaya ilişkin cümle doğru veya yanlış olur.'
  ], 'Önerme, öncül ve sonuç örneklerini; ardından doğruluk-geçerlilik-tutarlılık ayrımını birlikte incele.', 'Doğru çıkan bir sonuç, bütün akıl yürütmenin geçerli olduğunu gösterir mi?', 'Hayır. Sonuç tesadüfen doğru olabilir; geçerlilik, sonucun öncüllerden zorunlu olarak çıkıp çıkmadığıyla sınanır.');
  patch('fel-01', 'Düşünme ve Dil İlişkisi - Felsefi Bir Görüşü veya Argümanı Sorgulama', [18], [
    'Düşünceler kavramlarla ifade edilir; aynı sözcük farklı anlamlarda kullanıldığında görünüşte bir uzlaşma veya anlaşmazlık oluşabilir. “Özgürlük” bir cümlede dış engelin yokluğu, başkasında akla göre karar verme anlamında kullanılıyorsa iki görüşü karşılaştırmadan önce anlamlar açılmalıdır. Dilin açıklığı yalnız güzel anlatım değil, argümanın hangi iddiayı savunduğunun anlaşılması için gereklidir.',
    'Bir görüşü sorgularken sonuç iddiasını, onu destekleyen öncülleri ve belirtilmemiş varsayımları ayır. “Bu çözüm ucuz, öyleyse mutlaka en iyisidir.” çıkarımı iyiliğin tek ölçütünün maliyet olduğu varsayımını saklar. Güvenlik veya adalet gibi başka ölçütler varsa sonuç zorunlu değildir. Görüş sahibine saldırmak yerine gerekçenin konuyla ilgisini denetle. Karşı örnek iddianın kapsamını sınar; bir sözü hangi bağlamda söylendiğini yok sayarak eleştirmek gerçek argümanı değerlendirmek olmaz. Böylece eleştiri basit itirazdan gerekçeli incelemeye dönüşür.'
  ], 'Kavram, dil ve argüman sorgulama aşamalarında iddia ile gerekçeyi ayrı işaretle.', '“Bu görüşü genç biri söyledi, o hâlde yanlıştır.” çıkarımında sorun nedir?', 'Görüşün içeriği ve gerekçesi yerine kişinin özelliği değerlendiriliyor; yaş tek başına doğruluk ölçütü değildir.');
  patch('fel-02', 'Bilgi Felsefesinin Konusu ve Bilginin İmkânı Problemi', [27,28], [
    'Bilgi felsefesi yalnız hangi bilgilere sahip olduğumuzu değil, bilmenin neye dayandığını ve ne kadar güvenilir olduğunu sorar. Kaynak, ölçüt, sınır ve imkân problemleri farklıdır. “Bilgi deneyden gelir.” kaynak;“kesin bilgi mümkün değildir.” imkân problemine yanıt verir. Bir filozofun cevabını önce hangi soruya verdiğini belirlemek benzer terimleri karıştırmayı önler.',
    'Septik yaklaşım algı yanılmaları ve görüş ayrılıklarından hareketle kesinliğe kuşkuyla bakar; bu tavır her gündelik iddianın yanlış olduğunu kanıtlamakla aynı değildir. Dogmatik yaklaşım doğru bilginin mümkün olduğunu kabul eder; felsefi kullanımda sözcük yalnız düşünmeden inat etmek anlamına gelmez. Bilginin mümkün olduğunu kabul eden düşünürler kaynağı konusunda yine ayrılabilir. Bir nesnenin su içinde farklı görünmesi duyuların eleştirel incelenmesini gerektirir; bundan hiçbir koşulda hiçbir bilgi elde edilemeyeceği sonucu ek gerekçe olmadan çıkmaz.'
  ], 'Bilginin soruları listesini, septik ve dogmatik yaklaşımların imkân problemine verdiği yanıtlarla karşılaştır.', '“Doğru bilgiye ulaşılır ama bunun kaynağı akıldır.” yargısı hangi iki problemi yanıtlar?', 'Bilginin imkânını olumlu yanıtlar ve kaynağını akıl olarak belirler; imkân ile kaynak ayrı sorulardır.');
  patch('fel-03', 'Varlık Felsefesi Alanındaki Çağdaş Yaklaşımlar', [23,24], [
    'Çağdaş varlık yaklaşımları aynı soruya aynı ölçütle cevap vermez. Husserl’in fenomenolojisi varlığın bilince nasıl verildiğini ve özünü betimlemeyi öne çıkarır; bunu sıradan bir duyu izlenimini sorgusuz kabul etmekle özdeşleştirme. Hartmann’ın yeni ontolojisi ise inorganik, organik, ruhsal ve tinsel katmanları ayırır. Üst katmanın altına dayanması, bütün özelliklerinin alt katmana indirgenebileceği anlamına gelmez.',
    'Pragmatizm düşünceleri sonuçları ve problem çözmedeki işlevleriyle değerlendirir. Varoluşçulukta özellikle Sartre, insanın hazır bir özle belirlenmek yerine seçimleriyle kendini kurmasını vurgular. Bu iki yaklaşım “insan” sözcüğünü kullansa da biri fayda ve deneyim, diğeri varoluş ve özgür seçim merkezlidir. Bir alıntıyı yalnız filozof adıyla değil hangi kavrama ne görev verdiğiyle eşleştir. “Kendi özünü oluşturmak” sorumluluktan kaçmak değil, kişinin seçimini kendisine ait kabul etmesi bağlamında okunur.'
  ], 'Fenomenoloji, yeni ontoloji, pragmatizm ve varoluşçuluk paragraflarında temel açıklama ölçütünü ayır.', 'Hartmann’da organik katmanın inorganiğe dayanması canlılığın bütün özelliklerinin fizik bilgisiyle açıklanacağı anlamına gelir mi?', 'Hayır. Katman ayrımı üst düzeyin kendine özgü niteliklerini de korur; dayanma ile bütünüyle indirgenme aynı değildir.');
  patch('fel-03', 'Değerlendirilmesi', [25,26], [
    'Bu sayfaların temel sorusu evrende amaç ve düzenin nasıl açıklanacağıdır. Nedensellik, bir olayın hangi koşullardan doğduğunu; amaçlılık ise bir son veya hedef için gerçekleşip gerçekleşmediğini sorar. “Yağmur basınç ve nem koşullarında oluşur.” nedensel açıklamadır;“yağmur belirli bir amaç için vardır.” farklı bir iddiadır. Düzen gözlemekten belirli bir amacı zorunlu çıkarmak ayrıca gerekçe ister.',
    'Varlık türlerini sınıflandırırken duyusal-nesnel varlıkla düşünsel varlığı ayır. Bir ağaç ile matematiksel üçgenin var olma biçimi aynı soru çerçevesinde tartışılabilir ama aynı fiziksel nesne türü değildir. Edebî bir hikâyede benlik, zaman veya gerçeklik sorunlarının bulunması da varlık felsefesinin yalnız soyut terimlerden ibaret olmadığını gösterir. Bir görüşü değerlendirirken açıklama ölçütünü, varsaydığı varlık türünü ve alternatif yorumu göster. Kendi inanç veya beğenini görüşün mantıksal gerekçesi yerine koymadan karşılaştırma yap.'
  ], 'Kaynağın “Evrende Amaçlılık ve Düzenlilik–Varlık Türlerinin Sınıflandırılması” başlığını ve sonundaki değerlendirme bölümünü izle.', 'Bir olayın nedenini açıklamak onun bir amaç için gerçekleştiğini de kanıtlar mı?', 'Hayır. Nedensellik geçmiş/koşul ilişkisini, amaçlılık hedef veya son ilişkisini tartışır; ikisi ayrı iddialardır.');
  patch('fel-04', 'Ahlak Felsefesinin Konusu ve Problemleri - İyi ve Kötünün Ölçütü', [37,38,39], [
    'Ahlak toplumda benimsenen davranış kurallarını, etik bu kuralların ve iyi-kötü ölçütlerinin felsefi incelemesini belirtir. “Bu toplumda şu davranış beğenilir.” betimleyici;“bu davranış yapılmalıdır.” normatif bir yargıdır. Bir kuralın yaygın olması onu gerekçelendirmek için tek başına yeterli değildir. İrade, vicdan, özgürlük ve sorumluluk da aynı kavramın farklı adları değil, ahlaki eylemin farklı yönleridir.',
    'İyiliğin ölçütü filozofa göre mutluluk, haz, fayda veya ödev olabilir. Bentham açısından çok sayıda kişinin yararı öne çıkarken Kant’ta eylemin ödevden ve iyi istençten doğması belirleyicidir. Aynı yardım davranışı farklı niyet ve ölçütlerle değerlendirilir:yalnız çıkar elde etmek için yapmakla doğru olduğu için yapmak aynı gerekçe değildir. Aristoteles’in ölçülülük düşüncesini her durumda aritmetik orta seçmek sanma; uygun eylem ve erdem bağlamı önemlidir. Önce ölçütü bul, sonra örneği o ölçüte göre yorumla.'
  ], 'Ahlaki kavram tablosunu ve filozofların mutluluk-haz-fayda-ödev ölçütlerini karşılaştır.', 'Aynı davranışın sonucu iyi olsa da Kant açısından neden farklı değerlendirilebilir?', 'Eylemin hangi niyet ve ilkeyle yapıldığı önemlidir; yalnız sonuç ödevden eylemi belirlemeye yetmez.');
  patch('fel-04', 'Evrensel Bir Ahlak Yasasını Reddeden Görüşler ve Filozoflar', [44,45], [
    'Evrensel ahlak yasası sorusu bütün insanlar için aynı bağlayıcı ölçütün bulunup bulunmadığını tartışır. Böyle bir yasayı reddetmek, hiç kimsenin hiçbir değerinin olmadığı anlamına gelmez; değerin kaynağı birey, kültür veya seçime dayandırılabilir. Anarşist yaklaşım baskıcı otorite ve zorlamanın özgürlük üzerindeki etkisini tartışır; onu yalnız gündelik düzensizlik anlamında okumak felsefi iddiayı kaçırır.',
    'Nietzsche mevcut değerlerin eleştirisini ve bireyin değer yaratmasını; Sartre önceden belirlenmiş insan özü yerine seçimi öne çıkarır. İkisini aynı cümleyle “istediğini yap” öğüdüne indirgemek hem kavramsal ayrımı hem sorumluluk boyutunu siler. Sartre’da insanın kendini seçimleriyle kurması, yaptığının sorumluluğunu üstlenmesini de gerektirir. Bir metinde bireyin vurgulanması tek başına bencillik görüşünü kanıtlamaz; evrensel kuralın neden reddedildiğine ve yerine hangi temel konduğuna bak. Karşılaştırma farklı düşünürlerin özgürlük anlayışlarını görünür kılar.'
  ], 'Evrensellik sorusunu, anarşizm ve Nietzsche-Sartre paragraflarının ayrı gerekçeleriyle eşleştir.', 'Evrensel yasa reddedildiğinde otomatik olarak bütün eylemler eşit derecede iyi mi olur?', 'Hayır. Evrensel tek ölçüt yerine başka değer kaynakları savunulabilir; reddin kapsamı bütün değerlendirmeleri yok etmek zorunda değildir.');
  patch('fel-04', 'İyilik ve Mutluluk İlişkisi - Özgürlük, Sorumluluk ve Kural İlişkisi', [46,47,48], [
    'İyi eylem ile mutlu hissetme birlikte bulunabilir fakat tanım gereği aynı değildir. Kişinin hoşuna giden bir sonuç başkasına zarar verebilir. Bazı filozoflar mutluluğu ruhsal dinginlik veya aşırılıktan kaçınmayla, başkaları ahlaki erdemle ilişkilendirir. Kant açısından ödevin ölçütünü yalnız kişiye haz vermesine bağlamak uygun değildir. Böylece “niçin iyi davranırım” sorusu ile“hangi durumda mutlu olurum” sorusu birbirinden ayrılır.',
    'Özgürlük ve sorumluluk tartışmasında kişinin bilgiye, seçeneklere ve dış baskıya sahip olma durumu incelenir. Akran baskısı karar koşullarını etkileyebilir ama kişinin hiçbir seçimi kalmadığını kendiliğinden kanıtlamaz. Kaynaktaki spor salonu örneğinde kuralları bilme, katılma kararı ve ortaya çıkan zarar ayrı aşamalardır. Kurala uymak her zaman kör itaat, özgürlük de her isteği sınırsız uygulamak demek değildir. Birlikte yaşarken başkalarının haklarının da bulunduğunu kabul etmek özgürlüğün sınırlarını gerekçelendirme sorusunu doğurur.'
  ], 'Mutluluk görüşlerini ve spor salonu örneğinde bilgi, seçim, baskı, sonuç ilişkisini ayrı incele.', '“Arkadaşlarım istedi.” demek ahlaki sorumluluğu tek başına kaldırır mı?', 'Hayır. Baskının derecesi ve kişinin karar imkânı ayrıca değerlendirilir; başkasının istemesi kişinin hiçbir tercihi olmadığını göstermez.');
  patch('fel-05', 'Bilimin Değeri - Bilim Felsefe İlişkisi - Bilim ve Hayat İlişkisi', [35,36], [
    'Bilimin kuramsal değeri evreni anlama ve açıklama ihtiyacını; pratik değeri bilgiyle sorun çözme ve yaşam koşullarını değiştirmeyi öne çıkarır. Bir araştırmanın hemen ürüne dönüşmemesi değersiz olduğunu göstermez. Buna karşılık teknik bir başarının mümkün olması onun bütün kullanımlarının ahlaken iyi olduğunu kanıtlamaz. Bilgi üretimiyle kullanım kararının değer boyutları ayrı tartışılır.',
    'Bilim ve felsefe merak, gerekçe, tutarlılık ve eleştirellikte ortaklaşabilir; deneysel sınama ve bütünsel kavramsal sorgulama bakımından yöntem farkları taşır. Bilim felsefesi belirli bir deneyi yapmak yerine bilimin yöntemi, açıklaması ve sınırını inceler. Felsefenin bilim verilerinden yararlanması veya bilim insanlarının felsefi sorular sorması iki alanı aynı yöntem hâline getirmez. Kaynaktaki ortak/farklı özellikleri kesin bir kopuş tablosu gibi değil, ilişki içinde ayır. “Bilim yararlıdır.” iddiası da yararın kime, hangi kullanımda ve hangi bedelle sağlandığı sorularıyla ayrıntı kazanır.'
  ], 'Kuramsal/pratik değer ayrımını bilim-felsefe ortaklık ve yöntem farkları tablosuyla birlikte oku.', 'Bir bilimsel bilginin kötü amaçla kullanılabilmesi onun açıklama doğruluğunu otomatik çürütür mü?', 'Hayır. Açıklamanın doğruluğu ile kullanımın ahlaki değeri farklı değerlendirmelerdir; ikisi de ayrıca incelenmelidir.');
  patch('fel-07', 'Egemenlik Sorunu - Toplumsal Sorunlara Felsefi Bakış', [59,60], [
    'Egemenlik siyasi karar alma gücünü, meşruiyet bu gücün hangi gerekçeyle haklı sayıldığını sorgular. Bir iktidarın fiilen güçlü olması onun her kararının haklı olduğunu tek başına kanıtlamaz. Kaynağın asalet, kutsallık, bilgelik veya halk iradesi gibi temellere bakması, otoritenin farklı şekillerde gerekçelendirilebildiğini gösterir. İktidarın kaynağı, kullanım şekli ve sınırları ayrı sorulardır.',
    'Birey-devlet ilişkisi hak ve özgürlüklerin korunmasıyla birlikte değerlendirilir. Toplumsal bir sorun hakkında yalnız kişisel hoşnutsuzluk bildirmek yerine hangi hak, değer veya kurumun etkilendiğini açıklamak felsefi bakıştır. Teknoloji ve küresel etkileşim yeni sorunlar doğurabilir; önceden düzenlenmemiş olması sorunun önemsiz olduğunu göstermez. Bir çözümün güvenlik sağlamasıyla özgürlük üzerindeki etkisi birlikte tartışılabilir. İki değerin gerilimini fark etmek herhangi birini gerekçesiz yok saymak değil, uygulanacak sınırın nedenini açıkça savunmaktır.'
  ], 'Egemenliğin kaynağı ve sınırlarıyla, toplumsal sorunun hak/değer boyutunu ayrı işaretle.', 'İktidarın güçlü olması ile meşru olması aynı iddia mıdır?', 'Hayır. İlki fiilî güç kapasitesine, ikincisi yönetme hakkının hangi gerekçeyle kabul edildiğine ilişkindir.');
})();
